const lessons = [
  {"num": 7, "time": "00:01:00,000 --> 00:01:22,599", "arabic": "إِنْ رَأَيْتُكِ تَجْلِسِينَ هُنَا مَرَّةً ثَانِيَةً", "segs": null, "full_uz": "Seni bu yerda yana bir bor o'tirganingni ko'rsam.", "note": null},
  {"num": 8, "time": "00:01:22,599 --> 00:01:24,579", "arabic": "رَمَيْتُكِ خَارِجَ هَذِهِ الدَّارِ", "segs": null, "full_uz": "Seni bu uydan tashqariga otib yuboraman.", "note": null},
  {"num": 9, "time": "00:01:24,579 --> 00:01:25,900", "arabic": "صَدِّقِينِي يَا زُمُرُّدُ", "segs": null, "full_uz": "Ishon menga, Zumurrud.", "note": null},
  {"num": 10, "time": "00:01:25,900 --> 00:01:28,079", "arabic": "إِنِ اسْتَمْرَرْتِ بِطَرِيقَةِ تَفْكِيرِكِ هَذِهِ", "segs": null, "full_uz": "Agar shu fikrlash tarzingda davom etsang.", "note": null},
  {"num": 11, "time": "00:01:28,079 --> 00:01:29,299", "arabic": "سَنَخْسَرُ كُلَّ شَيْءٍ", "segs": null, "full_uz": "Hammasidan judo bo'lamiz.", "note": null},
  {"num": 12, "time": "00:01:29,299 --> 00:01:31,319", "arabic": "وَلَنْ يَشْتَرِيَهَا أَحَدٌ بَعْدَ الَّذِي فَعَلْتِهِ", "segs": null, "full_uz": "Qilganingdan keyin uni hech kim sotib olmaydi.", "note": null},
  {"num": 13, "time": "00:01:31,319 --> 00:01:34,120", "arabic": "وَفَوْقَ كُلِّ ذَلِكَ سَتَمُوتُ إِنْ مَا أُعْطِيَ عَنْهَا الطَّعَامُ أَكْثَرَ", "segs": null, "full_uz": "Bundan tashqari, agar unga ko'proq ovqat berilmasa, u o'ladi.", "note": null},
  {"num": 15, "time": "00:01:40,979 --> 00:01:44,500", "arabic": "مِثْلُهَا لَا يَسْتَحِقُّ إِلَّا الْمَوْتَ", "segs": null, "full_uz": "Uning kabilar faqat o'limga loyiq.", "note": null},
  {"num": 16, "time": "00:01:44,500 --> 00:01:46,579", "arabic": "بَلِ الْمَوْتُ كَثِيرٌ عَلَيْهَا", "segs": null, "full_uz": "Yo'q, o'lim unga ko'p ham keladi.", "note": null},
  {"num": 17, "time": "00:01:46,579 --> 00:01:49,239", "arabic": "وَمَاذَا سَنَجْنِي مِنْ مَوْتِهَا غَيْرَ السِّجْنِ؟", "segs": null, "full_uz": "Uning o'limidan zindondan boshqa nima olamiz?", "note": null},
  {"num": 18, "time": "00:01:49,239 --> 00:01:52,920", "arabic": "أَرْجُوكِ يَا زُمُرُّدُ لَا تَدَعِي غَضَبَكِ يَقُودُنَا إِلَى التَّهْلُكَةِ أَرْجُوكِ", "segs": [{"ar": "أَرْجُوكِ يَا زُمُرُّدُ لَا تَدَعِي غَضَبَكِ يَقُودُنَا إِلَى التَّهْلُكَةِ", "uz": "iltimos, Zumurrud, g'azabing bizni halokatga еtaklab bormasin"}, {"ar": "أَرْجُوكِ", "uz": "iltimos"}], "full_uz": "Iltimos, Zumurrud, g'azabing bizni halokatga еtaklab bormasin, iltimos.", "note": null},
  {"num": 20, "time": "00:02:29,300 --> 00:02:33,939", "arabic": "لَمْ أَتْرُكْ مَكَانًا فِي بَغْدَادَ إِلَّا بَحَثْتُ فِيهِ عَنْكُمَا دُونَ جَدْوَى", "segs": null, "full_uz": "Bag'dodda hech qanday joyni tashlab qo'ymay, ikkovingizni qidirdim, lekin foydasiz.", "note": null},
  {"num": 21, "time": "00:02:33,939 --> 00:02:36,300", "arabic": "أَيْنَ ذَهَبْتُمَا؟", "segs": null, "full_uz": "Qayerga ketdinglar?", "note": null},
  {"num": 22, "time": "00:02:38,140 --> 00:02:46,460", "arabic": "لَكِنَّنِي لَنْ أَيْأَسَ مِنَ الْعُثُورِ عَلَيْكُمَا", "segs": null, "full_uz": "Lekin sizlarni topishdan umidimni uzmayman.", "note": null},
  {"num": 23, "time": "00:02:46,460 --> 00:02:51,620", "arabic": "لَنْ أَتْرُكَ زَاوِيَةً فِي بَغْدَادَ إِلَّا وَسَأَبْحَثُ فِيهَا عَنْكُمَا", "segs": null, "full_uz": "Bag'dodning hech bir burchagini qidirmay qoldirmayman.", "note": null},
  {"num": 24, "time": "00:02:51,620 --> 00:02:54,120", "arabic": "اَللَّهُمَّ رُدَّ لِي ابْنَتِي", "segs": null, "full_uz": "Ey Alloh, qizimni menga qaytar.", "note": null},
  {"num": 26, "time": "00:02:59,300 --> 00:03:04,939", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 27, "time": "00:03:04,939 --> 00:03:08,280", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 28, "time": "00:03:08,280 --> 00:03:10,400", "arabic": "أَسْتَطِيعُ مُسَاعَدَتَكَ يَا عَمِّي", "segs": null, "full_uz": "Sizga yordam bera olamanmi, amaki?", "note": null},
  {"num": 29, "time": "00:03:10,400 --> 00:03:12,520", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا وَلَدِي", "segs": null, "full_uz": "Alloh senga yaxshilik ato etsin, o'g'lim.", "note": null},
  {"num": 30, "time": "00:03:12,520 --> 00:03:14,960", "arabic": "إِنَّمَا كُنْتُ أَرْتَاحُ مِنْ وَعْثَاءِ السَّفَرِ", "segs": null, "full_uz": "Men shunchaki safar mashaqqatidan dam olayotgan edim.", "note": null},
  {"num": 31, "time": "00:03:14,960 --> 00:03:17,360", "arabic": "كَمْ أَلَمَنِي عَنَاءُ الطَّرِيقِ", "segs": null, "full_uz": "Yo'l mashaqqati meni naqadar charchatdi.", "note": null},
  {"num": 32, "time": "00:03:17,360 --> 00:03:18,640", "arabic": "كَانَ اللَّهُ فِي الْعَوْنِ", "segs": null, "full_uz": "Alloh yordamchi bo'lsin.", "note": null},
  {"num": 34, "time": "00:03:19,980 --> 00:03:20,780", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 35, "time": "00:03:20,780 --> 00:03:21,920", "arabic": "وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Va sizga ham salom.", "note": null},
  {"num": 36, "time": "00:03:29,300 --> 00:03:35,860", "arabic": "يَا رَبِّ", "segs": null, "full_uz": "Ey Robbim.", "note": null},
  {"num": 38, "time": "00:03:38,180 --> 00:03:44,719", "arabic": "صَدِّقِينِي يَا زُمُرُّدُ", "segs": null, "full_uz": "Ishon menga, Zumurrud.", "note": null},
  {"num": 39, "time": "00:03:44,719 --> 00:03:47,420", "arabic": "بِالْقَسْوَةِ لَنْ تَصِلِي مَعَهَا إِلَى أَيِّ نَتِيجَةٍ", "segs": null, "full_uz": "Qattiqqo'llik bilan u bilan hech qanday natijaga erisha olmaysan.", "note": null},
  {"num": 40, "time": "00:03:47,420 --> 00:03:50,700", "arabic": "دَعِينَا نُجَرِّبِ اللِّينَ عَلَّهَا تَكُونُ طَرِيقَةً جَيِّدَةً", "segs": null, "full_uz": "Keling, yumshoqlikni sinab ko'raylik, balki yaxshi usul bo'lar.", "note": null},
  {"num": 41, "time": "00:03:50,700 --> 00:03:52,860", "arabic": "جَرَّبْتُ مَعَهَا اللِّينَ", "segs": null, "full_uz": "Men u bilan yumshoqlikni sinab ko'rdim.", "note": null},
  {"num": 42, "time": "00:03:52,860 --> 00:03:54,640", "arabic": "وَلَكِنَّهُ لَمْ يُجْدِ", "segs": null, "full_uz": "Lekin foyda bermadi.", "note": null},
  {"num": 43, "time": "00:03:54,640 --> 00:03:56,520", "arabic": "أَنْتِ جَرَّبْتِ وَلَمْ تُفْلِحِي", "segs": null, "full_uz": "Sen sinab ko'rding-u, muvaffaq bo'lmading.", "note": null},
  {"num": 44, "time": "00:03:56,520 --> 00:03:57,720", "arabic": "دَعِينِي أُجَرِّبُ أَنَا", "segs": null, "full_uz": "Menga o'zim sinab ko'rishimga ijozat ber.", "note": null},
  {"num": 45, "time": "00:03:57,719 --> 00:03:59,560", "arabic": "وَإِنْ لَمْ أَنْجَحْ افْعَلِي بِهَا مَا تَشَائِينَ", "segs": null, "full_uz": "Agar muvaffaq bo'lmasam, u bilan xohlagan narsangni qil.", "note": null},
  {"num": 46, "time": "00:03:59,560 --> 00:04:03,319", "arabic": "وَكَيْفَ سَتُقْنِعُهَا أَيُّهَا الذَّكِيُّ؟", "segs": null, "full_uz": "Uni qanday ko'ndirasan, ey aqlli?", "note": null},
  {"num": 47, "time": "00:04:03,319 --> 00:04:03,759", "arabic": "قُلْ لِي", "segs": null, "full_uz": "Ayt-chi.", "note": null},
  {"num": 48, "time": "00:04:03,759 --> 00:04:07,020", "arabic": "إِنْ قُلْتُ لَكِ إِنَّنِي أَعْرِفُ سَأَكُونُ كَاذِبًا", "segs": null, "full_uz": "Agar senga bilaman desam, yolg'onchi bo'laman.", "note": null},
  {"num": 49, "time": "00:04:07,020 --> 00:04:10,620", "arabic": "لَكِنْ قَلْبِي يُحَدِّثُنِي أَنَّنِي سَأَنْجَحُ فِي تَلْيِينِ رَأْسِهَا", "segs": null, "full_uz": "Lekin yuragim menga uning qaysar boshini yumshatishga muvaffaq bo'lishimni aytyapti.", "note": null},
  {"num": 50, "time": "00:04:10,620 --> 00:04:13,079", "arabic": "دَعِينَا نُحَاوِلُ لَنْ نَخْسَرَ شَيْئًا", "segs": null, "full_uz": "Keling, urinib ko'raylik, hech narsa yo'qotmaymiz.", "note": null},
  {"num": 51, "time": "00:04:13,079 --> 00:04:16,180", "arabic": "حَسَنًا يَا حَنْظَلَةُ", "segs": null, "full_uz": "Xo'p, Hanzala.", "note": null},
  {"num": 52, "time": "00:04:16,180 --> 00:04:18,779", "arabic": "سَأَنْزِلُ عِنْدَ رَغْبَتِكَ هَذِهِ الْمَرَّةَ", "segs": null, "full_uz": "Bu safar sening istagingga ko'nay.", "note": null},
  {"num": 53, "time": "00:04:18,779 --> 00:04:20,360", "arabic": "وَلَكِنْ إِنْ لَمْ تُفْلِحْ", "segs": null, "full_uz": "Lekin agar muvaffaq bo'lmasang.", "note": null},
  {"num": 54, "time": "00:04:20,360 --> 00:04:23,019", "arabic": "لَأَجْعَلَنَّ أَنَّهَا تَشْتَهِي الْمَوْتَ وَلَا تَنَالُهُ", "segs": null, "full_uz": "Uni o'limni orzu qiladigan-u, unga yeta olmaydigan holga solaman.", "note": null},
  {"num": 55, "time": "00:04:23,019 --> 00:04:23,819", "arabic": "اِذْهَبْ", "segs": null, "full_uz": "Bor.", "note": null},
  {"num": 56, "time": "00:04:27,720 --> 00:04:36,320", "arabic": "أَتُرَى سَتَمُنُّ عَلَيَّ الْأَيَّامُ بِرُؤْيَةِ أَهْلِي مَرَّةً أُخْرَى؟", "segs": null, "full_uz": "Qiziq, kunlar menga yaqinlarimni yana bir bor ko'rish ne'matini berarmikan?", "note": null},
  {"num": 57, "time": "00:04:38,320 --> 00:04:42,320", "arabic": "أَيُعْقَلُ أَنْ أَتَزَوَّجَ دُونَ أَنْ أَجِدَ حَوْلِي أَهْلِي؟", "segs": null, "full_uz": "Yaqinlarim atrofimda bo'lmasdan turib turmush qurishim mumkinmi?", "note": null},
  {"num": 58, "time": "00:04:43,520 --> 00:04:50,320", "arabic": "أَيُّ سَعَادَةٍ تِلْكَ الَّتِي سَأَشْعُرُ بِهَا وَأَنَا أَتَزَوَّجُ بَعِيدًا عَنْ أَهْلِي؟", "segs": null, "full_uz": "Yaqinlarimdan yiroqda turmush qursam, qanday baxtni his qilaman?", "note": null},
  {"num": 59, "time": "00:04:57,720 --> 00:05:03,440", "arabic": "أَخْرُجُ وَحِيدَةً إِلَى بَيْتِ زَوْجِي؟", "segs": null, "full_uz": "Erimning uyiga yolg'iz o'zim chiqib ketamanmi?", "note": null},
  {"num": 60, "time": "00:05:04,820 --> 00:05:10,440", "arabic": "أَلَنْ يَسِيرَ مَعِي أَبِي وَأُمِّي وَأُخْتِي فَوْزُ إِلَى بَيْتِ زَوْجِي؟", "segs": null, "full_uz": "Otam, onam va opam Fawz meni erimning uyigacha kuzatib qo'yishmaydimi?", "note": null},
  {"num": 61, "time": "00:05:11,320 --> 00:05:13,440", "arabic": "كَمَا يُفْعَلُ مَعَ الْعَرُوسِ؟", "segs": null, "full_uz": "Kelinlar bilan qilinganidek?", "note": null},
  {"num": 62, "time": "00:05:15,460 --> 00:05:20,440", "arabic": "أَيْنَ أَنْتَ الْآنَ يَا أَبِي؟", "segs": null, "full_uz": "Hozir qayerdasan, otajon?", "note": null},
  {"num": 63, "time": "00:05:22,360 --> 00:05:24,440", "arabic": "أَيْنَ أَنْتِ الْآنَ يَا فَوْزُ؟", "segs": null, "full_uz": "Hozir qayerdasan, Fawz?", "note": null},
  {"num": 64, "time": "00:05:24,439 --> 00:05:28,699", "arabic": "أَتَتْرُكَانِنِي فِي سَاعَةٍ مِثْلِ هَذِهِ؟", "segs": null, "full_uz": "Meni shunday bir vaqtda tashlab ketasizlarmi?", "note": null},
  {"num": 65, "time": "00:05:28,699 --> 00:05:44,159", "arabic": "اَللَّهُمَّ", "segs": null, "full_uz": "Ey Alloh.", "note": null},
  {"num": 66, "time": "00:05:44,159 --> 00:05:50,060", "arabic": "كَمَا جَمَعْتَ يُوسُفَ بِأَبِيهِ وَإِخْوَتِهِ", "segs": null, "full_uz": "Yusufni otasi va akalari bilan qanday qovushtirgan bo'lsang.", "note": null},
  {"num": 67, "time": "00:05:50,060 --> 00:05:53,819", "arabic": "اِجْمَعْنِي بِأَهْلِي عَمَّا قَرِيبٍ", "segs": null, "full_uz": "Meni ham tez orada yaqinlarim bilan qovushtirgin.", "note": null},
  {"num": 68, "time": "00:05:53,819 --> 00:05:56,899", "arabic": "يَا رَبِّ", "segs": null, "full_uz": "Ey Robbim.", "note": null},
  {"num": 70, "time": "00:06:00,800 --> 00:06:03,339", "arabic": "صَدِّقِينِي يَا فَوْزُ", "segs": null, "full_uz": "Ishon menga, Fawz.", "note": null},
  {"num": 71, "time": "00:06:03,339 --> 00:06:08,560", "arabic": "لَنْ تَنَالِي بِعِنَادِكِ هَذَا إِلَّا الْجُوعَ وَالْعَطَشَ وَالْعَذَابَ وَالسَّوْطَ", "segs": null, "full_uz": "Bu o'jarliging bilan faqat ochlik, chanqoqlik, azob va qamchiga erishasan.", "note": null},
  {"num": 72, "time": "00:06:08,560 --> 00:06:11,000", "arabic": "زَوْجَتِي وَأَعْرِفُهَا", "segs": null, "full_uz": "U mening xotinim, uni bilaman.", "note": null},
  {"num": 73, "time": "00:06:11,000 --> 00:06:13,680", "arabic": "هِيَ أَعْنَدُ مَخْلُوقٍ عَلَى وَجْهِ الْأَرْضِ", "segs": null, "full_uz": "U yer yuzidagi eng o'jar mavjudot.", "note": null},
  {"num": 74, "time": "00:06:13,680 --> 00:06:17,180", "arabic": "إِنْ أَرَادَتْ شَيْئًا أَصَرَّتْ أَنْ تَحْصُلَ عَلَيْهِ", "segs": null, "full_uz": "Bir narsani istasa, unga erishishda qat'iyat qiladi.", "note": null},
  {"num": 75, "time": "00:06:17,180 --> 00:06:21,539", "arabic": "اِخْدَعِيهَا أَوْ أَوْهِمِيهَا أَنَّكِ مُوَافِقَةٌ عَلَى بَيْعِكِ", "segs": null, "full_uz": "Uni aldab yoki sotilishga rozi ekaningni his qildirib qo'y.", "note": null},
  {"num": 76, "time": "00:06:21,540 --> 00:06:23,800", "arabic": "لَنْ يَشْتَرِيَكِ أَحَدٌ بِهَذَا الْمَنْظَرِ", "segs": null, "full_uz": "Bu ko'rinishing bilan seni hech kim sotib olmaydi.", "note": null},
  {"num": 77, "time": "00:06:23,800 --> 00:06:28,900", "arabic": "أَرْجُوكِ دَعِينَا نَكْسَبِ الْوَقْتَ", "segs": null, "full_uz": "Iltimos, vaqt yutaylik.", "note": null},
  {"num": 78, "time": "00:06:28,900 --> 00:06:32,220", "arabic": "لَوْ كُنْتُ مَكَانَكِ لَوَافَقْتُ أَنْ أُبَاعَ لِأَيِّ عَابِرِ سَبِيلٍ", "segs": null, "full_uz": "Agar sening o'rningda bo'lsam, har qanday yo'lovchiga sotilishga rozi bo'lardim.", "note": null},
  {"num": 79, "time": "00:06:32,220 --> 00:06:33,960", "arabic": "عَلَى أَنْ أَبْقَى فِي بَيْتِ زُمُرُّدَ", "segs": null, "full_uz": "Zumurrudning uyida qolganimdan ko'ra.", "note": null},
  {"num": 80, "time": "00:06:33,960 --> 00:06:36,640", "arabic": "أَرْجُوكِ وَافِقِي", "segs": null, "full_uz": "Iltimos, rozi bo'l.", "note": null},
  {"num": 81, "time": "00:06:36,640 --> 00:06:43,240", "arabic": "وَافِقِي", "segs": null, "full_uz": "Rozi bo'l.", "note": null},
  {"num": 82, "time": "00:06:43,240 --> 00:06:49,680", "arabic": "كُنْتُ أَعْرِفُ أَنَّكِ فَتَاةٌ طَيِّبَةٌ وَذَكِيَّةٌ وَتَعْرِفِينَ مَصْلَحَتَكِ جَيِّدًا", "segs": null, "full_uz": "Sen yaxshi va aqlli qiz ekaningni, o'z manfaatingni yaxshi bilishingni bilardim.", "note": null},
  {"num": 83, "time": "00:06:51,540 --> 00:06:54,540", "arabic": "مِنَ الْآنِ فَصَاعِدًا سَتُعَامِلُكِ", "segs": null, "full_uz": "Bundan buyon u senga munosabatda bo'ladi.", "note": null},
  {"num": 84, "time": "00:06:54,540 --> 00:06:55,939", "arabic": "بِإِذْنِ اللَّهِ بِأَفْضَلِ مُعَامَلَةٍ", "segs": null, "full_uz": "Alloh xohlasa, eng yaxshi munosabat bilan.", "note": null},
  {"num": 85, "time": "00:06:55,939 --> 00:06:57,300", "arabic": "وَلَنْ تَخْسَرِي أَيَّ شَيْءٍ", "segs": null, "full_uz": "Va hech narsa yo'qotmaysan.", "note": null},
  {"num": 87, "time": "00:07:27,300 --> 00:07:33,120", "arabic": "اَللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ نُورُ السَّمَاوَاتِ وَالْأَرْضِ وَلَكَ الْحَمْدُ", "segs": null, "full_uz": "Ey Alloh, hamd Senga xosdir, Sen osmonlar va yerning nurisan, hamd Senga xosdir.", "note": "Rasululloh sallallohu alayhi vasallamning tungi namoz duosidan (Buxoriy, Muslim)."},
  {"num": 88, "time": "00:07:33,120 --> 00:07:37,420", "arabic": "أَنْتَ قَيِّمُ السَّمَاوَاتِ وَالْأَرْضِ وَلَكَ الْحَمْدُ", "segs": null, "full_uz": "Sen osmonlar va yerni ushlab turuvchisan, hamd Senga xosdir.", "note": null},
  {"num": 89, "time": "00:07:37,420 --> 00:07:42,379", "arabic": "اَللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ وَعَلَيْكَ تَوَكَّلْتُ", "segs": null, "full_uz": "Ey Alloh, Senga bo'ysundim, Senga iymon keltirdim va Senga tavakkal qildim.", "note": null},
  {"num": 90, "time": "00:07:42,379 --> 00:07:46,720", "arabic": "وَإِلَيْكَ أَنَبْتُ وَبِكَ خَاصَمْتُ وَإِلَيْكَ حَاكَمْتُ", "segs": null, "full_uz": "Senga tavba qildim, Sen bilan kurashdim va nizolarimni Senga hakam qildim.", "note": null},
  {"num": 91, "time": "00:07:46,720 --> 00:07:51,879", "arabic": "اَللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ", "segs": null, "full_uz": "Ey Alloh, ilgari qilgan va keyinga qoldirgan gunohlarimni mag'firat qil.", "note": null},
  {"num": 92, "time": "00:07:51,879 --> 00:07:54,660", "arabic": "وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ", "segs": null, "full_uz": "Va yashirgan hamda oshkor qilgan gunohlarimni ham.", "note": null},
  {"num": 93, "time": "00:07:54,660 --> 00:07:57,860", "arabic": "أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ", "segs": null, "full_uz": "Sen ilgari suruvchisan va Sen kechiktiruvchisan.", "note": null},
  {"num": 94, "time": "00:07:57,860 --> 00:08:00,820", "arabic": "لَا إِلَهَ إِلَّا أَنْتَ", "segs": null, "full_uz": "Sendan o'zga iloh yo'q.", "note": null},
  {"num": 95, "time": "00:08:00,820 --> 00:08:22,820", "arabic": "مَا هِيَ إِلَّا أَيَّامٌ قَلِيلَةٌ تَتَحَسَّنُ صِحَّتُهَا وَتَزُولُ آثَارُ الْكَدَمَاتِ عَنْ وَجْهِهَا", "segs": null, "full_uz": "Bir necha kun ichida sog'lig'i yaxshilanadi va yuzidagi ko'karish izlari yo'qoladi.", "note": null},
  {"num": 96, "time": "00:08:22,819 --> 00:08:26,540", "arabic": "عَلَيْنَا أَنْ نَبْدَأَ بِالْبَحْثِ عَنْ شَارِيهَا الْيَوْمَ قَبْلَ الْغَدِ", "segs": null, "full_uz": "Ertadan ko'ra bugundanoq unga xaridor qidirishni boshlashimiz kerak.", "note": null},
  {"num": 97, "time": "00:08:26,540 --> 00:08:29,459", "arabic": "أَلَا نَنْتَظِرُ قَلِيلًا حَتَّى تَتَحَسَّنَ تَمَامًا؟", "segs": null, "full_uz": "Butunlay tuzalguncha ozgina kutmaymizmi?", "note": null},
  {"num": 98, "time": "00:08:29,459 --> 00:08:32,120", "arabic": "لَا نُرِيدُ أَنْ نَخْسَرَ الْمَالَ بَعْدَ كُلِّ الَّذِي فَعَلْنَاهُ", "segs": null, "full_uz": "Qilgan hamma ishimizdan keyin pulni yo'qotishni xohlamaymiz.", "note": null},
  {"num": 99, "time": "00:08:32,120 --> 00:08:34,779", "arabic": "لَا لَا لَا لَا يَهُمُّنِي أَنْ نَخْسَرَ بَعْضَ الْمَالِ", "segs": null, "full_uz": "Yo'q, yo'q, yo'q, bir oz pul yo'qotishimiz farqi yo'q.", "note": null},
  {"num": 100, "time": "00:08:34,779 --> 00:08:38,299", "arabic": "اَلْمُهِمُّ عِنْدِي أَنْ أَتَخَلَّصَ مِنْ هَذِهِ الْمَأْفُونَةِ", "segs": null, "full_uz": "Mening uchun muhimi — bu ahmoqdan qutulish.", "note": "«مَأْفُونَة» — aqli kam, ahmoq ayol ma'nosida."},
  {"num": 101, "time": "00:08:38,299 --> 00:08:39,159", "arabic": "كَمَا تُرِيدِينَ", "segs": null, "full_uz": "Xohlaganingizdek.", "note": null},
  {"num": 102, "time": "00:08:39,159 --> 00:08:43,159", "arabic": "مَعَ إِشْرَاقِ الشَّمْسِ الْغَدَ تَبْدَأُ الْبَحْثَ عَنْ شَارِيهَا فَهِمْتَ؟", "segs": null, "full_uz": "Ertaga quyosh chiqishi bilan unga xaridor qidirishni boshlaysan, tushundingmi?", "note": null},
  {"num": 104, "time": "00:09:22,820 --> 00:09:44,680", "arabic": "اَلْحَقِيقَةُ يَا شَيْخَنَا أَنِّي قَصَدْتُكَ فِي أَمْرٍ يَخُصُّ أَحْمَدَ بْنَ حَنْبَلٍ", "segs": null, "full_uz": "Rostini aytsam, ustozimiz, Ahmad ibn Hanbalga tegishli bir ish uchun sizga keldim.", "note": null},
  {"num": 105, "time": "00:09:44,680 --> 00:09:46,820", "arabic": "وَمَا هُوَ يَا ابْنَ نُوحٍ؟", "segs": null, "full_uz": "Nima ekan, Ibn Nuh?", "note": null},
  {"num": 106, "time": "00:09:47,820 --> 00:09:49,600", "arabic": "لَا أَدْرِي مَاذَا سَأَقُولُ", "segs": null, "full_uz": "Nima deyishimni bilmayapman.", "note": null},
  {"num": 107, "time": "00:09:49,600 --> 00:09:56,460", "arabic": "إِنَّ أَحْمَدَ فِي حَالَةِ فَقْرٍ وَعَوَزٍ لَا يَعْلَمُهَا أَحَدٌ إِلَّا اللَّهُ وَحْدَهُ", "segs": null, "full_uz": "Ahmad shunday qashshoqlik va muhtojlik holatidaki, buni faqat Allohning O'zi biladi.", "note": null},
  {"num": 108, "time": "00:09:56,460 --> 00:09:59,879", "arabic": "وَقَدْ عَانَى فِي سَابِقِ أَيَّامِهِ مِنْ مَرَارَةِ هَذَا الْفَقْرِ", "segs": null, "full_uz": "U o'tgan kunlarida shu qashshoqlikning achchiqligini boshdan kechirgan.", "note": null},
  {"num": 109, "time": "00:09:59,879 --> 00:10:02,680", "arabic": "وَكَادَ عَوَزُهُ يَصْرِفُهُ عَنْ طَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Va uning muhtojligi uni ilm talabidan chalg'itay dedi.", "note": null},
  {"num": 110, "time": "00:10:02,680 --> 00:10:05,500", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 111, "time": "00:10:05,500 --> 00:10:12,159", "arabic": "اِسْمَعْ يَا مُحَمَّدُ حَسَنًا فَعَلْتَ وَنِعْمَ الصَّدِيقُ أَنْتَ", "segs": null, "full_uz": "Eshit, Muhammad, yaxshi qilding, sen naqadar yaxshi do'stsan.", "note": null},
  {"num": 112, "time": "00:10:12,159 --> 00:10:16,700", "arabic": "اَلْفَقْرُ يَا بُنَيَّ لَا يَصْرِفُ إِلَّا النُّفُوسَ الضَّعِيفَةَ عَنْ طَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Qashshoqlik, o'g'lim, faqat zaif ruhlarnigina ilm talabidan chalg'itadi.", "note": null},
  {"num": 113, "time": "00:10:16,700 --> 00:10:19,900", "arabic": "وَصَدِيقُكَ ابْنُ حَنْبَلٍ ذُو رَأْيٍ وَعَزِيمَةٍ", "segs": null, "full_uz": "Do'sting Ibn Hanbal esa fikrli va qat'iyatli inson.", "note": null},
  {"num": 114, "time": "00:10:19,900 --> 00:10:22,840", "arabic": "وَلَنْ يُعِيقَهُ شَيْءٌ عَنْ مُتَابَعَةِ طَرِيقِهِ", "segs": null, "full_uz": "Hech narsa uni o'z yo'lida davom etishdan to'sa olmaydi.", "note": null},
  {"num": 115, "time": "00:10:22,840 --> 00:10:24,640", "arabic": "سَأُعْطِيكَ بَعْضَ الْمَالِ", "segs": null, "full_uz": "Senga bir oz pul beraman.", "note": null},
  {"num": 116, "time": "00:10:24,640 --> 00:10:26,400", "arabic": "اِدْفَعْهُ إِلَيْهِ", "segs": null, "full_uz": "Uni unga bergin.", "note": null},
  {"num": 117, "time": "00:10:26,400 --> 00:10:27,540", "arabic": "عَلَّهَا تُعِينُهُ", "segs": null, "full_uz": "Balki bu unga yordam berar.", "note": null},
  {"num": 118, "time": "00:10:27,540 --> 00:10:28,620", "arabic": "يَا شَيْخَنَا", "segs": null, "full_uz": "Ustozimiz.", "note": null},
  {"num": 119, "time": "00:10:28,620 --> 00:10:30,680", "arabic": "إِنَّ أَحْمَدَ كَمَا قُلْتَ", "segs": null, "full_uz": "Ahmad, aytganingizdek.", "note": null},
  {"num": 120, "time": "00:10:30,680 --> 00:10:32,520", "arabic": "صَاحِبُ رَأْيٍ وَعَزِيمَةٍ", "segs": null, "full_uz": "Fikrli va qat'iyatli inson.", "note": null},
  {"num": 121, "time": "00:10:32,520 --> 00:10:34,600", "arabic": "وَلَنْ يَقْبَلَ أَيَّ عَطَاءٍ مِنْ أَيِّ أَحَدٍ", "segs": null, "full_uz": "Va hech kimdan hech qanday in'omni qabul qilmaydi.", "note": null},
  {"num": 122, "time": "00:10:34,600 --> 00:10:36,500", "arabic": "حَتَّى لَوْ كَانَ مِنْ ذَوِي الْقُرْبَى إِلَيْهِ", "segs": null, "full_uz": "Hatto o'ziga yaqin qarindoshlaridan bo'lsa ham.", "note": null},
  {"num": 123, "time": "00:10:36,500 --> 00:10:40,060", "arabic": "إِنَّ عِزَّةَ نَفْسِهِ أَعْيَتْنَا نَحْنُ أَصْحَابَهُ مِنْ قَبْلُ", "segs": null, "full_uz": "Uning izzat-nafsi ilgari ham bizni, uning do'stlarini, ojiz qoldirgan.", "note": null},
  {"num": 124, "time": "00:10:40,060 --> 00:10:42,600", "arabic": "وَمَا الْعَمَلُ إِذَنْ يَا ابْنِي؟", "segs": null, "full_uz": "Unda nima qilish kerak, o'g'lim?", "note": null},
  {"num": 125, "time": "00:10:43,460 --> 00:10:45,420", "arabic": "لَوْ سَاعَدْتَنَا فِي أَنْ نَجِدَ لَهُ عَمَلًا", "segs": null, "full_uz": "Agar unga ish topishimizga yordam bersangiz.", "note": null},
  {"num": 126, "time": "00:10:45,419 --> 00:10:49,099", "arabic": "يُعِينُهُ عَلَى أَعْبَاءِ الْحَيَاةِ وَلَا يُؤَخِّرُهُ عَنْ دَرْسِهِ", "segs": null, "full_uz": "Turmush yukiga yordam beradigan, lekin darsidan orqada qoldirmaydigan.", "note": null},
  {"num": 127, "time": "00:10:49,099 --> 00:10:52,099", "arabic": "عَمَلٌ؟ وَأَيُّ عَمَلٍ؟", "segs": null, "full_uz": "Ishmi? Qanaqa ish?", "note": null},
  {"num": 128, "time": "00:10:52,099 --> 00:10:55,519", "arabic": "عَجِّلْ يَا شَيْخَنَا فَعَمَلُهُ لَنْ يَصْرِفَهُ عَنْ طَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Tezroq bo'ling, ustozimiz, uning ishi ilm talabidan chalg'itmaydi.", "note": null},
  {"num": 129, "time": "00:10:55,519 --> 00:10:58,679", "arabic": "حَسَنًا سَأَرَى مَا يُمْكِنُ فِعْلُهُ", "segs": null, "full_uz": "Xo'p, nima qilish mumkinligini ko'raman.", "note": null},
  {"num": 130, "time": "00:10:58,679 --> 00:11:00,019", "arabic": "هَيَّا إِلَى الدَّرْسِ", "segs": null, "full_uz": "Yur, darsga.", "note": null},
  {"num": 131, "time": "00:11:06,740 --> 00:11:13,599", "arabic": "أَرَى يَا مَوْلَايَ أَنَّ فِي يَدِ جَعْفَرِ بْنِ يَحْيَى مِنَ الْأَعْبَاءِ مَا يَكْفِيهِ عَنْ وِلَايَةِ خُرَاسَانَ", "segs": null, "full_uz": "Menimcha, xo'jayinim, Ja'far ibn Yahyoning qo'lida allaqachon Xuroson hokimligini ortiqcha qiladigan yuklar bor.", "note": null},
  {"num": 132, "time": "00:11:13,600 --> 00:11:20,639", "arabic": "وَهَلْ أَنْتَ خَائِفٌ مِنْهُ أَمْ عَلَيْهِ يَا ابْنَ الرَّبِيعِ؟", "segs": null, "full_uz": "Sen undan qo'rqasanmi yoki u haqida xavotirdamisan, Ibn Rabi?", "note": null},
  {"num": 133, "time": "00:11:20,639 --> 00:11:25,659", "arabic": "إِخْلَاصِي لِأَمِيرِ الْمُؤْمِنِينَ يَقُولُ", "segs": null, "full_uz": "Mo'minlar amiriga sadoqatim shuni aytadi.", "note": null},
  {"num": 134, "time": "00:11:25,659 --> 00:11:28,379", "arabic": "كِلَاهُمَا عِنْدِي سَوَاءٌ", "segs": null, "full_uz": "Ikkalasi ham men uchun barobar.", "note": null},
  {"num": 135, "time": "00:11:28,379 --> 00:11:32,420", "arabic": "مَا دُمْتُ عُمْرِي أَخْدُمُ أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Umrim bo'yi mo'minlar amiriga xizmat qilar ekanman.", "note": null},
  {"num": 136, "time": "00:11:39,320 --> 00:11:41,019", "arabic": "اِسْمَعْ يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Eshit, Ibn Rabi.", "note": null},
  {"num": 137, "time": "00:11:41,019 --> 00:11:43,000", "arabic": "سَمِيعًا دَعَوْتَ يَا مَوْلَايَ", "segs": null, "full_uz": "Eshituvchi kishini chaqirdingiz, xo'jayinim.", "note": null},
  {"num": 138, "time": "00:11:43,000 --> 00:11:46,059", "arabic": "لَوْ أَنَّ غَيْرَكَ كَلَّمَنِي فِي شَأْنِ جَعْفَرٍ", "segs": null, "full_uz": "Agar sendan boshqasi menga Ja'far haqida gapirganida.", "note": null},
  {"num": 139, "time": "00:11:46,059 --> 00:11:49,039", "arabic": "لَسَمِعَ مِنِّي مَا لَا يُحِبُّ وَيَرْضَى", "segs": null, "full_uz": "Yoqmaydigan va rozi bo'lmaydigan gaplarni mendan eshitardi.", "note": null},
  {"num": 140, "time": "00:11:49,039 --> 00:11:51,980", "arabic": "وَلَكِنَّكَ تَعْلَمُ يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Lekin sen bilasan, Ibn Rabi.", "note": null},
  {"num": 141, "time": "00:11:51,980 --> 00:11:55,179", "arabic": "لَكَ فِي قَلْبِي مَنْزِلَةٌ", "segs": null, "full_uz": "Yuragimda o'z o'rning bor.", "note": null},
  {"num": 142, "time": "00:11:55,179 --> 00:11:56,539", "arabic": "أَرْجُو", "segs": null, "full_uz": "Umid qilaman.", "note": null},
  {"num": 143, "time": "00:11:56,539 --> 00:12:00,440", "arabic": "أَلَّا تَحْمِلَكَ عَلَى قَوْلِ مَا لَا يَنْبَغِي", "segs": null, "full_uz": "Bu seni aytilishi kerak bo'lmagan gapga undamasin.", "note": null},
  {"num": 144, "time": "00:12:00,440 --> 00:12:01,919", "arabic": "وَمَا لَا أُحِبُّ سَمَاعَهُ", "segs": null, "full_uz": "Va eshitishni yoqtirmagan narsaga.", "note": null},
  {"num": 145, "time": "00:12:01,919 --> 00:12:05,059", "arabic": "وَهَذَا مَا أَطْلَقَ لِسَانِي عَلَى قَوْلِ ذَلِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Aynan shu narsa tilimni shuni aytishga ochdi, xo'jayinim.", "note": null},
  {"num": 146, "time": "00:12:05,059 --> 00:12:06,639", "arabic": "اِسْمَعْ يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Eshit, Ibn Rabi.", "note": null},
  {"num": 147, "time": "00:12:06,639 --> 00:12:10,500", "arabic": "أَنَا أَعْلَمُ أَنَّكَ لَا تُحِبُّ جَعْفَرًا", "segs": null, "full_uz": "Men bilaman, Ja'farni yoqtirmaysan.", "note": null},
  {"num": 148, "time": "00:12:10,500 --> 00:12:18,539", "arabic": "أَمَّا خَوْفُكَ مِنْهُ فَهُوَ مَا لَا أُحِبُّ أَنْ أَسْمَعَهُ مِنْكَ مَرَّةً أُخْرَى", "segs": null, "full_uz": "Undan qo'rqishingga kelsak, buni sendan boshqa marta eshitishni yoqtirmayman.", "note": null},
  {"num": 149, "time": "00:12:18,539 --> 00:12:22,860", "arabic": "إِنْ كُنْتَ حَرِيصًا عَلَى مَقَامِكَ عِنْدَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Agar mo'minlar amiri huzuridagi maqomingga qadrdon bo'lsang.", "note": null},
  {"num": 150, "time": "00:12:22,860 --> 00:12:29,320", "arabic": "دَعْ جَعْفَرًا وَشَأْنَهُ يَا ابْنَ الرَّبِيعِ دَعْ جَعْفَرًا وَشَأْنَهُ", "segs": null, "full_uz": "Ja'farni o'z holiga qo'y, Ibn Rabi, Ja'farni o'z holiga qo'y.", "note": null},
  {"num": 151, "time": "00:12:29,320 --> 00:12:33,379", "arabic": "مَوْلَايَ أَمِيرَ الْمُؤْمِنِينَ إِنَّمَا هِيَ هَوَاجِسُ نَفْسِي لَا غَيْرُ", "segs": null, "full_uz": "Xo'jayinim, mo'minlar amiri, bular faqat mening ichki xavotirlarim, xolos.", "note": null},
  {"num": 152, "time": "00:12:33,379 --> 00:12:36,399", "arabic": "وَأَنْتَ مَنْ عَوَّدَنِي أَنْ لَا أَكْتُمَ عَنْكَ شَيْئًا", "segs": null, "full_uz": "Sizdan hech narsani yashirmaslikka o'zingiz meni o'rgatgansiz.", "note": null},
  {"num": 153, "time": "00:12:40,500 --> 00:12:45,879", "arabic": "جَنِّبْ هَوَاجِسَكَ جَعْفَرًا يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Xavotirlaringni Ja'fardan yiroq tut, Ibn Rabi.", "note": null},
  {"num": 154, "time": "00:12:45,879 --> 00:12:49,639", "arabic": "جَنِّبْ هَوَاجِسَكَ جَعْفَرًا", "segs": null, "full_uz": "Xavotirlaringni Ja'fardan yiroq tut.", "note": null},
  {"num": 155, "time": "00:12:49,639 --> 00:12:52,299", "arabic": "كَمَا يَشَاءُ مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinim xohlaganidek.", "note": null},
  {"num": 156, "time": "00:13:05,779 --> 00:13:07,580", "arabic": "أَمَّا بَعْدُ", "segs": null, "full_uz": "Ammo ba'd.", "note": null},
  {"num": 157, "time": "00:13:07,580 --> 00:13:14,800", "arabic": "فَقَدْ سَمِعْنَا أَقْوَامًا يُنْكِرُونَ سُنَّةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Rasululloh (sollallohu alayhi va sallam) sunnatini inkor qiladigan qavmlarni eshitdik.", "note": null},
  {"num": 158, "time": "00:13:14,800 --> 00:13:16,759", "arabic": "صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Allohning salovoti va salomi u zotga bo'lsin.", "note": null},
  {"num": 159, "time": "00:13:16,759 --> 00:13:18,900", "arabic": "وَاللَّهُ قَالَ فِي كِتَابِهِ", "segs": null, "full_uz": "Alloh O'z kitobida aytdi.", "note": null},
  {"num": 160, "time": "00:13:18,900 --> 00:13:25,300", "arabic": "وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا", "segs": null, "full_uz": "Payg'ambar sizlarga nima bergan bo'lsa, uni oling, va nimadan qaytargan bo'lsa, undan tiyilinglar.", "note": "Qur'ondagi (Hashr, 7-oyat) iqtibos."},
  {"num": 161, "time": "00:13:25,300 --> 00:13:31,080", "arabic": "وَلَوْ تَأَمَّلْنَا لَوَجَدْنَا أَنَّ اللَّهَ أَمَرَنَا فِي كِتَابِهِ", "segs": null, "full_uz": "Agar tafakkur qilsak, Alloh O'z kitobida bizga buyurganini ko'ramiz.", "note": null},
  {"num": 162, "time": "00:13:31,080 --> 00:13:35,320", "arabic": "بِفَرَائِضِ الْإِسْلَامِ كَالصَّلَاةِ وَالزَّكَاةِ وَالْحَجِّ", "segs": null, "full_uz": "Namoz, zakot va haj kabi islom farzlarini.", "note": null},
  {"num": 163, "time": "00:13:35,320 --> 00:13:40,280", "arabic": "وَلَمْ يُبَيِّنْ لَنَا صِفَاتِهَا وَمَقَادِيرَهَا", "segs": null, "full_uz": "Lekin ularning sifatlari va miqdorlarini bayon qilmagan.", "note": null},
  {"num": 164, "time": "00:13:40,280 --> 00:13:45,480", "arabic": "بَلْ جَاءَ ذَلِكَ عَلَى لِسَانِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Balki bu Uning elchisi (sollallohu alayhi va sallam) tili orqali kelgan.", "note": null},
  {"num": 165, "time": "00:13:45,480 --> 00:13:53,000", "arabic": "فَبَيَّنَ لَنَا عَدَدَ مَا فُرِضَ مِنَ الصَّلَوَاتِ وَمَوَاقِيتَهَا وَسُنَنَهَا", "segs": null, "full_uz": "U bizga farz qilingan namozlarning sonini, vaqtlarini va sunnatlarini bayon qildi.", "note": null},
  {"num": 166, "time": "00:13:53,000 --> 00:13:59,340", "arabic": "وَنِصَابَ الزَّكَاةِ وَمَوَاقِيتَهُ وَوَاجِبَاتِ الْحَجِّ وَأَعْمَالَ الْعُمْرَةِ", "segs": null, "full_uz": "Zakotning nisobi va vaqtlarini, haj vojiblari va umra amallarini ham.", "note": null},
  {"num": 167, "time": "00:13:59,340 --> 00:14:05,920", "arabic": "وَهَذَا كُلُّهُ بَيَانٌ وَاضِحٌ لِحُجِّيَّةِ السُّنَّةِ", "segs": null, "full_uz": "Bularning barchasi sunnatning dalil ekanligining aniq bayonidir.", "note": null},
  {"num": 168, "time": "00:14:05,920 --> 00:14:13,100", "arabic": "فَقَاتَلَ اللَّهُ مَنْ فَرَّقَ بَيْنَ كَلَامِ اللَّهِ وَسُنَّةِ نَبِيِّهِ", "segs": null, "full_uz": "Alloh so'zi bilan payg'ambari sunnatini ajratganlarga Alloh la'nat aytsin.", "note": null},
  {"num": 169, "time": "00:14:13,100 --> 00:14:16,899", "arabic": "وَاللَّهُ سُبْحَانَهُ وَتَعَالَى أَعْلَمُ", "segs": null, "full_uz": "Alloh subhanahu va taolo bilguvchiroqdir.", "note": null},
  {"num": 170, "time": "00:14:16,899 --> 00:14:24,519", "arabic": "وَهَلْ خَلَتِ الدِّيَارُ مِنَ النِّسَاءِ حَتَّى تَعْجِزَ أُمُّكَ عَنْ إِيجَادِ عَرُوسٍ لَكَ؟", "segs": null, "full_uz": "Yurt ayollardan bo'shab qoldimi, onang senga kelin topa olmay qoldi?", "note": null},
  {"num": 171, "time": "00:14:24,519 --> 00:14:27,540", "arabic": "كُنْتُ أَفْقِدُ عَقْلِي يَا أَبَا دُلَامَةَ قَبْلَ أَنْ يَتِمَّ أَمْرِي", "segs": null, "full_uz": "Ishim bitmaguncha aqldan ozib qolayozdim, Abu Dulama.", "note": null},
  {"num": 172, "time": "00:14:27,539 --> 00:14:30,939", "arabic": "أَخْشَى أَنْ يَبْغَتَ الْمَوْتُ أُمِّي قَبْلَ أَنْ تَجِدَ لِي عَرُوسًا", "segs": null, "full_uz": "Onam menga kelin topmasdan turib, o'lim uni to'satdan olib ketishidan qo'rqaman.", "note": null},
  {"num": 173, "time": "00:14:30,939 --> 00:14:36,759", "arabic": "فَإِذَنِ ادْعُ اللَّهَ أَنْ يُطِيلَ فِي عُمْرِ أُمِّكَ حَتَّى تَجِدَ لَكَ عَرُوسًا", "segs": null, "full_uz": "Unda Allohga onangning umrini uzaytirishini so'ra, toki senga kelin topsin.", "note": null},
  {"num": 174, "time": "00:14:36,759 --> 00:14:44,259", "arabic": "أَخْشَى أَنْ تَلْقَى أُمِّي حَتْفَهَا قَبْلَ أَنْ تَجِدَ لِي عَرُوسًا", "segs": null, "full_uz": "Onam menga kelin topmasdan turib, ajali yetib qolishidan qo'rqaman.", "note": null},
  {"num": 175, "time": "00:14:44,259 --> 00:14:48,980", "arabic": "أُمِّي أُمِّي الْحَمْدُ لِلَّهِ عَلَى سَلَامَتِكِ", "segs": null, "full_uz": "Onajon, onajon, sog'-omon ekaningizga hamdlar bo'lsin.", "note": null},
  {"num": 176, "time": "00:14:48,980 --> 00:14:52,759", "arabic": "سَلَامَتِي؟ سَلَامَتِي مِنْ مَاذَا أَيُّهَا الْأَحْمَقُ؟", "segs": null, "full_uz": "Sog'-omonligimmi? Nimadan sog'-omonligim, ey ahmoq?", "note": null},
  {"num": 177, "time": "00:14:52,759 --> 00:14:55,959", "arabic": "أَحَسِبْتُكِ مُتِّ لَا لَا لَا لَا شَيْءَ لَا شَيْءَ", "segs": null, "full_uz": "Vafot etdingiz deb o'yladim... yo'q, yo'q, yo'q, hech narsa, hech narsa.", "note": null},
  {"num": 178, "time": "00:14:55,960 --> 00:14:59,860", "arabic": "مَا أَكْثَرُ مَا تَتَمَنَّاهُ الْآنَ؟", "segs": null, "full_uz": "Hozir eng ko'p nimani orzu qilyapsan?", "note": null},
  {"num": 179, "time": "00:14:59,860 --> 00:15:00,680", "arabic": "اَلْآنَ الْآنَ؟", "segs": null, "full_uz": "Hoziroqmi?", "note": null},
  {"num": 180, "time": "00:15:00,680 --> 00:15:01,080", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 181, "time": "00:15:01,080 --> 00:15:03,320", "arabic": "أَنْ يُطِيلَ اللَّهُ عُمْرَكِ", "segs": null, "full_uz": "Alloh umringizni uzaytirishini tilayman.", "note": null},
  {"num": 182, "time": "00:15:03,320 --> 00:15:07,920", "arabic": "أَنْتَ طَيِّبٌ رَغْمَ كُلِّ مَا فِيكَ", "segs": null, "full_uz": "Sen o'zingdagi hamma narsaga qaramay, mehribonsan.", "note": null},
  {"num": 183, "time": "00:15:07,920 --> 00:15:13,680", "arabic": "لَقَدْ وَجَدْتُ لَكَ عَرُوسًا", "segs": null, "full_uz": "Senga kelin topdim.", "note": null},
  {"num": 184, "time": "00:15:13,680 --> 00:15:16,620", "arabic": "حَقًّا فَعَلْتِ يَا أُمِّي؟", "segs": null, "full_uz": "Rostdanmi, onajon?", "note": null},
  {"num": 185, "time": "00:15:16,620 --> 00:15:16,980", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 186, "time": "00:15:16,980 --> 00:15:19,660", "arabic": "قُولِي لِي أَيْنَ تَسْكُنُ؟", "segs": null, "full_uz": "Ayting-chi, u qayerda yashaydi?", "note": null},
  {"num": 187, "time": "00:15:19,660 --> 00:15:20,700", "arabic": "كَمْ طُولُهَا؟ كَمْ عُمْرُهَا؟", "segs": null, "full_uz": "Bo'yi qancha? Yoshi nechada?", "note": null},
  {"num": 188, "time": "00:15:20,700 --> 00:15:21,820", "arabic": "مَاذَا تَأْكُلُ؟ مَاذَا تَشْرَبُ؟", "segs": null, "full_uz": "Nima yeydi? Nima ichadi?", "note": null},
  {"num": 189, "time": "00:15:21,820 --> 00:15:22,639", "arabic": "قُولِي يَا أُمِّي", "segs": null, "full_uz": "Ayting, onajon.", "note": null},
  {"num": 190, "time": "00:15:22,639 --> 00:15:23,620", "arabic": "عَلَى رِسْلِكَ", "segs": null, "full_uz": "Shoshilma.", "note": null},
  {"num": 191, "time": "00:15:23,620 --> 00:15:25,740", "arabic": "إِنَّهَا ابْنَةُ الْقَصَّابِ", "segs": null, "full_uz": "U qassobning qizi.", "note": null},
  {"num": 192, "time": "00:15:25,740 --> 00:15:28,399", "arabic": "فَتَاةٌ فِي غَايَةِ الْأَدَبِ", "segs": null, "full_uz": "Juda odobli qiz.", "note": null},
  {"num": 193, "time": "00:15:28,399 --> 00:15:29,500", "arabic": "خَلُوقَةٌ", "segs": null, "full_uz": "Xushxulq.", "note": null},
  {"num": 194, "time": "00:15:29,500 --> 00:15:31,419", "arabic": "وَالْأَهَمُّ مِنْ هَذَا وَذَاكَ", "segs": null, "full_uz": "Bulardan ham muhimrog'i.", "note": null},
  {"num": 195, "time": "00:15:31,419 --> 00:15:33,659", "arabic": "لَهَا فَمٌ يَأْكُلُ وَلَا يَتَكَلَّمُ", "segs": null, "full_uz": "Uning og'zi yeydi-yu, gapirmaydi.", "note": null},
  {"num": 196, "time": "00:15:33,659 --> 00:15:36,620", "arabic": "مَاذَا تَقْصِدِينَ يَا أُمِّي؟", "segs": null, "full_uz": "Nimani nazarda tutyapsiz, onajon?", "note": null},
  {"num": 197, "time": "00:15:36,620 --> 00:15:39,419", "arabic": "خَرْسَاءُ؟", "segs": null, "full_uz": "Soqovmi?", "note": null},
  {"num": 198, "time": "00:15:39,419 --> 00:15:41,180", "arabic": "قَاتَلَ اللَّهُ غَبَاءَكَ", "segs": null, "full_uz": "Alloh ahmoqligingga la'nat aytsin.", "note": null},
  {"num": 199, "time": "00:15:41,180 --> 00:15:43,919", "arabic": "قَصَدْتُ أَنَّهَا فَتَاةٌ خَلُوقَةٌ", "segs": null, "full_uz": "Xushxulq qiz demoqchi edim.", "note": null},
  {"num": 200, "time": "00:15:43,919 --> 00:15:45,279", "arabic": "خَجُولَةٌ", "segs": null, "full_uz": "Uyatchan.", "note": null},
  {"num": 201, "time": "00:15:45,279 --> 00:15:46,639", "arabic": "اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Hamdlar bo'lsin.", "note": null},
  {"num": 202, "time": "00:15:46,639 --> 00:15:48,940", "arabic": "اَلْحَمْدُ لِلَّهِ حَسِبْتُ أَنَّهَا خَرْسَاءُ", "segs": null, "full_uz": "Hamdlar bo'lsin, soqov ekan deb o'yladim.", "note": null},
  {"num": 203, "time": "00:15:48,940 --> 00:15:50,860", "arabic": "قُولِي لِي يَا أُمِّي قُولِي لِي", "segs": null, "full_uz": "Ayting-chi, onajon, ayting.", "note": null},
  {"num": 204, "time": "00:15:50,860 --> 00:15:52,720", "arabic": "أَهِيَ جَمِيلَةٌ؟", "segs": null, "full_uz": "U chiroylimi?", "note": null},
  {"num": 205, "time": "00:15:52,720 --> 00:15:54,100", "arabic": "هَذَا مَا يُهِمُّكَ", "segs": null, "full_uz": "Seni shu qiziqtiradi.", "note": null},
  {"num": 206, "time": "00:15:54,100 --> 00:15:56,960", "arabic": "مَا يُهِمُّنِي الْأَخْلَاقُ", "segs": null, "full_uz": "Meni axloq qiziqtiradi.", "note": null},
  {"num": 207, "time": "00:15:56,960 --> 00:16:02,360", "arabic": "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "segs": null, "full_uz": "Barcha olamlarning Robbisi Allohga hamdlar bo'lsin.", "note": null},
  {"num": 208, "time": "00:16:02,360 --> 00:16:07,080", "arabic": "عَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Sizga ham salom.", "note": null},
  {"num": 210, "time": "00:16:08,399 --> 00:16:12,240", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 211, "time": "00:16:12,240 --> 00:16:15,159", "arabic": "أَحْمَدُ", "segs": null, "full_uz": "Ahmad.", "note": null},
  {"num": 212, "time": "00:16:15,159 --> 00:16:16,980", "arabic": "لَبَّيْكَ يَا شَيْخُ", "segs": null, "full_uz": "Labbay, ustoz.", "note": null},
  {"num": 213, "time": "00:16:16,980 --> 00:16:18,920", "arabic": "أُرِيدُكَ فِي أَمْرٍ مُهِمٍّ", "segs": null, "full_uz": "Senga muhim bir ish uchun kerakman.", "note": null},
  {"num": 214, "time": "00:16:18,920 --> 00:16:21,779", "arabic": "عَلِمْتُ أَنَّكَ تَبْحَثُ عَنْ عَمَلٍ", "segs": null, "full_uz": "Ish qidirayotganingni bildim.", "note": null},
  {"num": 215, "time": "00:16:21,779 --> 00:16:24,419", "arabic": "وَعِنْدِي لَكَ عَمَلٌ فِي دَارِ الْوَرَّاقِينَ", "segs": null, "full_uz": "Menda senga vorroqlar uyida ish bor.", "note": "«دار الوراقين» — qadimda qo'lyozmalar ko'chiriladigan va sotiladigan joy."},
  {"num": 216, "time": "00:16:24,419 --> 00:16:26,500", "arabic": "فَمَا رَأْيُكَ؟", "segs": null, "full_uz": "Fikring qanday?", "note": null},
  {"num": 217, "time": "00:16:26,500 --> 00:16:28,220", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا شَيْخَنَا", "segs": null, "full_uz": "Alloh sizga barakot bersin, ustozimiz.", "note": null},
  {"num": 218, "time": "00:16:28,220 --> 00:16:30,159", "arabic": "هَيَّا تَعَالَ مَعِي", "segs": null, "full_uz": "Yur, men bilan bor.", "note": null},
  {"num": 219, "time": "00:16:37,159 --> 00:16:39,079", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 220, "time": "00:16:39,079 --> 00:16:40,799", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 221, "time": "00:16:40,799 --> 00:16:44,279", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 222, "time": "00:16:44,279 --> 00:16:46,179", "arabic": "شَرَفٌ لَنَا أَنْ تَزُورَنَا يَا شَيْخَنَا", "segs": null, "full_uz": "Tashrif buyurishingiz biz uchun sharaf, ustozimiz.", "note": null},
  {"num": 223, "time": "00:16:46,179 --> 00:16:47,439", "arabic": "أَهْلًا بِكَ يَا ابْنَ مَعِينٍ", "segs": null, "full_uz": "Xush kelibsiz, Ibn Ma'in.", "note": null},
  {"num": 224, "time": "00:16:47,439 --> 00:16:51,759", "arabic": "لَقَدْ أَتَيْتُ بِهَذَا الشَّابِّ لِيَتَعَرَّفَ عَلَى مَكَانِ عَمَلِهِ الْجَدِيدِ", "segs": null, "full_uz": "Bu yigitni yangi ish joyi bilan tanishtirish uchun olib keldim.", "note": null},
  {"num": 225, "time": "00:16:51,759 --> 00:16:53,299", "arabic": "إِنَّهُ أَخُوكَ أَحْمَدُ", "segs": null, "full_uz": "U sening akang Ahmad.", "note": null},
  {"num": 226, "time": "00:16:53,299 --> 00:16:56,299", "arabic": "أَعْرِفُهُ جَيِّدًا يَا شَيْخَنَا إِنَّهُ صَدِيقِي", "segs": null, "full_uz": "Uni yaxshi bilaman, ustozimiz, u mening do'stim.", "note": null},
  {"num": 227, "time": "00:16:56,299 --> 00:17:01,120", "arabic": "حَقًّا؟ إِذَنْ خُذْ صَدِيقَكَ عَنِّي وَاكْفِنِي مُؤْنَةَ مَا جَاءَ مِنْ أَجْلِهِ", "segs": null, "full_uz": "Rostanmi? Unda do'stingni mendan olib, u nima uchun kelgan bo'lsa, o'sha ishni menga qilib ber.", "note": null},
  {"num": 228, "time": "00:17:01,120 --> 00:17:03,220", "arabic": "اَلسَّمْعُ وَالطَّاعَةُ يَا شَيْخُ", "segs": null, "full_uz": "Eshitish va bo'ysunish, ustoz.", "note": null},
  {"num": 229, "time": "00:17:03,220 --> 00:17:04,720", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا شَيْخُ", "segs": null, "full_uz": "Alloh sizga yaxshilik ato etsin, ustoz.", "note": null},
  {"num": 230, "time": "00:17:04,720 --> 00:17:06,019", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Xayr, sizga salom bo'lsin.", "note": null},
  {"num": 231, "time": "00:17:06,019 --> 00:17:07,180", "arabic": "وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Sizga ham salom.", "note": null},
  {"num": 232, "time": "00:17:07,180 --> 00:17:10,059", "arabic": "أَهْلًا بِأَحْمَدَ بْنِ حَنْبَلٍ", "segs": null, "full_uz": "Ahmad ibn Hanbalga xush kelibsiz.", "note": null},
  {"num": 233, "time": "00:17:10,059 --> 00:17:11,379", "arabic": "اُنْظُرْ", "segs": null, "full_uz": "Qara.", "note": null},
  {"num": 234, "time": "00:17:21,759 --> 00:17:30,740", "arabic": "لَا أَكَادُ أُصَدِّقُ عَيْنَيَّ يَا فَرَجُ", "segs": null, "full_uz": "Ko'zlarimga ishonolmayapman, Faraj.", "note": null},
  {"num": 235, "time": "00:17:30,740 --> 00:17:33,920", "arabic": "أَيُعْقَلُ أَنَّنَا سَنَسْكُنُ دَارًا كَسَائِرِ الْبَشَرِ؟", "segs": null, "full_uz": "Biz ham boshqa odamlar kabi bir uyda yashaymizmi?", "note": null},
  {"num": 236, "time": "00:17:33,920 --> 00:17:35,640", "arabic": "وَنَتْرُكُ أَكْوَاخَ الْقَصَّابِ", "segs": null, "full_uz": "Va qassoblik kulbalarini tark etamizmi?", "note": null},
  {"num": 237, "time": "00:17:35,640 --> 00:17:38,200", "arabic": "هَا أَنْتِ تَرَيْنَ هَذَا بِأُمِّ عَيْنِكِ يَا أُمَّ فَرَجٍ", "segs": null, "full_uz": "Mana, buni o'z ko'zing bilan ko'ryapsan, Umm Faraj.", "note": null},
  {"num": 238, "time": "00:17:38,200 --> 00:17:40,599", "arabic": "بَارَكَ اللَّهُ فِي مُعَلِّمِكَ بَهْزَاتَ", "segs": null, "full_uz": "Alloh ustozing Bahzatga barakot bersin.", "note": null},
  {"num": 239, "time": "00:17:40,599 --> 00:17:43,000", "arabic": "إِنَّ لَهُ فَضْلًا عَلَيْكَ بِإِقْرَاضِكَ الْمَالَ", "segs": null, "full_uz": "Senga pul qarz berib, seni minnatdor qilgan.", "note": null},
  {"num": 240, "time": "00:17:43,000 --> 00:17:44,859", "arabic": "حَتَّى تَسْتَأْجِرَ هَذِهِ الدَّارَ", "segs": null, "full_uz": "Toki shu uyni ijaraga olding.", "note": null},
  {"num": 241, "time": "00:17:44,859 --> 00:17:48,379", "arabic": "أَخِيرًا أَخِيرًا أَصْبَحْنَا كَسَائِرِ الْبَشَرِ يَا فَرَجُ", "segs": null, "full_uz": "Nihoyat, nihoyat, biz ham boshqa odamlarga o'xshab qoldik, Faraj.", "note": null},
  {"num": 242, "time": "00:17:51,759 --> 00:17:54,759", "arabic": "هَذِهِ تَبَاشِيرُ الطَّرِيقِ يَا أُمَّ الْفَرَجِ", "segs": null, "full_uz": "Bu yo'lning xushxabarlari, ey Umm Faraj.", "note": null},
  {"num": 243, "time": "00:17:54,759 --> 00:18:00,480", "arabic": "سَتَفْتَحُ الدُّنْيَا لَنَا ذِرَاعَيْهَا بِإِذْنِ اللَّهِ", "segs": null, "full_uz": "Alloh izni bilan dunyo bizga o'z quchog'ini ochadi.", "note": null},
  {"num": 244, "time": "00:18:00,480 --> 00:18:02,960", "arabic": "إِنْ شَاءَ اللَّهُ يَا فَرَجُ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, Faraj, Alloh xohlasa.", "note": null},
  {"num": 245, "time": "00:18:02,960 --> 00:18:11,019", "arabic": "هُنَا تُنْسَخُ كُتُبُ الْمَغَازِي وَالسِّيَرِ", "segs": null, "full_uz": "Bu yerda g'azovot va sira kitoblari ko'chiriladi.", "note": "«السِّيَر» — Payg'ambar hayoti va tarixiga oid asarlar."},
  {"num": 246, "time": "00:18:11,019 --> 00:18:14,180", "arabic": "وَتُنْسَخُ أَيْضًا الْأَحَادِيثُ النَّبَوِيَّةُ", "segs": null, "full_uz": "Va nabaviy hadislar ham ko'chiriladi.", "note": null},
  {"num": 247, "time": "00:18:14,180 --> 00:18:17,339", "arabic": "اَلصَّحِيحَةُ مِنْهَا وَالْمُدَلَّسُ فِيهَا", "segs": null, "full_uz": "Ularning sahihi ham, soxtalashtirilgani ham.", "note": null},
  {"num": 248, "time": "00:18:17,339 --> 00:18:21,180", "arabic": "اَلْمُدَلَّسُ فِيهَا؟", "segs": null, "full_uz": "Soxtalashtirilganimi?", "note": null},
  {"num": 249, "time": "00:18:21,180 --> 00:18:25,259", "arabic": "وَهَلْ ثَمَّ مَنْ يَتَجَرَّأُ عَلَى حَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟", "segs": null, "full_uz": "Rasululloh hadisiga tajovuz qiladigan kishi bormi?", "note": null},
  {"num": 250, "time": "00:18:25,259 --> 00:18:27,500", "arabic": "صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Allohning salovoti va salomi u zotga bo'lsin.", "note": null},
  {"num": 251, "time": "00:18:27,500 --> 00:18:29,060", "arabic": "أَجَلْ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Ha, Ibn Hanbal.", "note": null},
  {"num": 252, "time": "00:18:29,060 --> 00:18:32,340", "arabic": "هُنَاكَ مَنْ يُحَرِّفُ الْحَدِيثَ عَنْ مَوَاضِعِهِ", "segs": null, "full_uz": "Hadisni o'z o'rnidan burib talqin qiladiganlar bor.", "note": null},
  {"num": 253, "time": "00:18:32,340 --> 00:18:34,420", "arabic": "وَمِنْ بَعْدِ مَوَاضِعِهِ", "segs": null, "full_uz": "Va bundan tashqari.", "note": null},
  {"num": 254, "time": "00:18:34,420 --> 00:18:36,779", "arabic": "يَخْتَلِقُهُ وَيَبْتَدِعُهُ", "segs": null, "full_uz": "Uni to'qib chiqaradi va bid'at qiladi.", "note": null},
  {"num": 255, "time": "00:18:36,779 --> 00:18:38,980", "arabic": "وَيُزَوِّرُ فِي مَتْنِهِ وَإِسْنَادِهِ", "segs": null, "full_uz": "Uning matni va sanadida soxtakorlik qiladi.", "note": null},
  {"num": 256, "time": "00:18:38,980 --> 00:18:42,360", "arabic": "وَلِهَذَا أُنْشِئَ عِلْمُ الْإِسْنَادِ", "segs": null, "full_uz": "Shu sababdan sanad ilmi vujudga kelgan.", "note": null},
  {"num": 257, "time": "00:18:51,180 --> 00:19:02,600", "arabic": "يَا هَارُونُ", "segs": null, "full_uz": "Ey Horun.", "note": null},
  {"num": 259, "time": "00:19:04,640 --> 00:19:07,140", "arabic": "يَا مَفْتُونُ", "segs": null, "full_uz": "Ey aldangan!", "note": null},
  {"num": 260, "time": "00:19:07,140 --> 00:19:09,180", "arabic": "مَتَى تَعْقِلُ؟", "segs": null, "full_uz": "Qachon aqlingni ishlatasan?", "note": null},
  {"num": 261, "time": "00:19:12,820 --> 00:19:15,180", "arabic": "أَنَا الْمَجْنُونُ أَمْ مَنْ؟", "segs": null, "full_uz": "Jinni menmanmi, yoki kim?", "note": null},
  {"num": 262, "time": "00:19:15,700 --> 00:19:17,279", "arabic": "بَلْ أَنَا الْعَاقِلُ يَا هَارُونُ", "segs": null, "full_uz": "Yo'q, aqlli — menman, Horun.", "note": null},
  {"num": 263, "time": "00:19:21,180 --> 00:19:28,900", "arabic": "وَكَيْفَ يَكُونُ عَقْلُكَ هَذَا؟", "segs": null, "full_uz": "Bu aqling qanday bo'ladi?", "note": null},
  {"num": 264, "time": "00:19:28,900 --> 00:19:34,120", "arabic": "لِأَنِّي عَلِمْتُ أَنَّ قَصْرَكَ زَائِلٌ", "segs": null, "full_uz": "Chunki men saroying o'tkinchi ekanini bildim.", "note": null},
  {"num": 265, "time": "00:19:34,120 --> 00:19:35,820", "arabic": "وَأَنَّ هَذَا بَاقٍ", "segs": null, "full_uz": "Va bu esa boqiy ekanini.", "note": null},
  {"num": 266, "time": "00:19:35,820 --> 00:19:37,779", "arabic": "فَعَمَّرْتُ هَذَا", "segs": null, "full_uz": "Shuning uchun shuni obod qildim.", "note": null},
  {"num": 267, "time": "00:19:37,779 --> 00:19:41,600", "arabic": "أَمَّا أَنْتَ فَقَدْ عَمَّرْتَ قَصْرَكَ وَخَرَّبْتَ قَبْرَكَ", "segs": null, "full_uz": "Sen esa saroyingni obod qilib, qabringni vayron qilding.", "note": null},
  {"num": 268, "time": "00:19:41,600 --> 00:19:45,039", "arabic": "فَتَكْرَهُ أَنْ تَنْتَقِلَ مِنَ الْعُمْرَانِ إِلَى الْخَرَابِ", "segs": null, "full_uz": "Shuning uchun obodlikdan xarobaga o'tishni yomon ko'rasan.", "note": null},
  {"num": 269, "time": "00:19:45,039 --> 00:19:48,820", "arabic": "مَعَ أَنَّكَ تَعْلَمُ أَنَّكَ إِلَيْهِ صَائِرٌ لَا مَحَالَةَ", "segs": null, "full_uz": "Holbuki, sen albatta u yerga borishingni bilasan.", "note": null},
  {"num": 270, "time": "00:19:48,820 --> 00:19:51,000", "arabic": "أَتَيْتُ الْقُبُورَ فَنَادَيْتُهَا", "segs": null, "full_uz": "Qabrlarga keldim va ularga nido qildim.", "note": null},
  {"num": 271, "time": "00:19:51,000 --> 00:19:53,279", "arabic": "أَيْنَ الْمُعَظَّمُ وَالْمُحْتَقَرُ", "segs": null, "full_uz": "Qayerda ulug'langan va past ko'rilgan?", "note": null},
  {"num": 272, "time": "00:19:53,279 --> 00:19:55,400", "arabic": "وَأَيْنَ الْمُدِلُّ بِسُلْطَانِهِ", "segs": null, "full_uz": "Va o'z hukmronligi bilan mag'rurlanuvchi qayerda?", "note": null},
  {"num": 273, "time": "00:19:55,400 --> 00:19:57,460", "arabic": "وَأَيْنَ الْمُزَكَّى إِذَا مُفْتَخِرٌ", "segs": null, "full_uz": "Va faxrlanib, o'zini pok deb bilgan kishi qayerda?", "note": null},
  {"num": 274, "time": "00:19:57,460 --> 00:19:59,779", "arabic": "تَرُوحُ وَتَغْدُو بَنَاتُ الثَّرَى", "segs": null, "full_uz": "Tuproq qizlari kelib-ketaveradi.", "note": null},
  {"num": 275, "time": "00:19:59,779 --> 00:20:01,680", "arabic": "فَتَمْحُو مَحَاسِنَ تِلْكَ الصُّوَرِ", "segs": null, "full_uz": "Va o'sha qiyofalarning go'zalliklarini o'chirib tashlaydi.", "note": null},
  {"num": 276, "time": "00:20:01,680 --> 00:20:04,299", "arabic": "فَيَا سَائِلًا عَنْ أُنَاسٍ مَضَوْا", "segs": null, "full_uz": "Ey o'tib ketgan odamlar haqida so'rovchi.", "note": null},
  {"num": 277, "time": "00:20:04,299 --> 00:20:07,039", "arabic": "أَمَا لَكَ فِيمَا تَرَى مُعْتَبَرٌ", "segs": null, "full_uz": "Ko'rgan narsangda senga ibrat yo'qmi?", "note": null},
  {"num": 278, "time": "00:20:07,039 --> 00:20:10,339", "arabic": "أَلَا يَدْعُو هَذَا إِلَى الْجُنُونِ يَا هَارُونُ؟", "segs": null, "full_uz": "Bu jinnilikka olib bormaydimi, Horun?", "note": null},
  {"num": 279, "time": "00:20:10,339 --> 00:20:14,980", "arabic": "وَاللَّهِ إِنَّكَ لَصَادِقٌ", "segs": null, "full_uz": "Alloh haqqi, sen albatta haqgo'ysan.", "note": null},
  {"num": 280, "time": "00:20:14,980 --> 00:20:17,299", "arabic": "زِدْنِي", "segs": null, "full_uz": "Yana ayt.", "note": null},
  {"num": 281, "time": "00:20:17,299 --> 00:20:19,420", "arabic": "حَسْبُكَ كِتَابُ اللَّهِ", "segs": null, "full_uz": "Senga Alloh kitobi yetarli.", "note": null},
  {"num": 282, "time": "00:20:19,420 --> 00:20:20,400", "arabic": "فَالْزَمْهُ", "segs": null, "full_uz": "Unga yopish.", "note": null},
  {"num": 283, "time": "00:20:20,400 --> 00:20:22,620", "arabic": "فَفِيهِ الْخَبَرُ وَفِيهِ الْعِبَرُ", "segs": null, "full_uz": "Unda xabar ham, ibrat ham bor.", "note": null},
  {"num": 284, "time": "00:20:22,620 --> 00:20:28,500", "arabic": "لَكَ حَاجَةٌ فَأَقْضِيَهَا لَكَ؟", "segs": null, "full_uz": "Sening biror ehtiyoying bormi, uni bajarib beraymi?", "note": null},
  {"num": 285, "time": "00:20:28,500 --> 00:20:28,740", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 286, "time": "00:20:28,740 --> 00:20:32,560", "arabic": "ثَلَاثُ حَاجَاتٍ إِنْ قَضَيْتَهَا شَكَرْتُكَ", "segs": null, "full_uz": "Uch ehtiyoj bor, agar bajarsang, senga minnatdor bo'laman.", "note": null},
  {"num": 287, "time": "00:20:32,560 --> 00:20:34,840", "arabic": "فَاطْلُبْ إِذَنْ", "segs": null, "full_uz": "Unda so'ra.", "note": null},
  {"num": 288, "time": "00:20:34,840 --> 00:20:36,519", "arabic": "أَنْ تَزِيدَ فِي عُمْرِي", "segs": null, "full_uz": "Umrimni ko'paytirishingni.", "note": null},
  {"num": 289, "time": "00:20:36,519 --> 00:20:40,560", "arabic": "لَا أَسْتَطِيعُ", "segs": null, "full_uz": "Bunga qodir emasman.", "note": null},
  {"num": 290, "time": "00:20:40,560 --> 00:20:42,900", "arabic": "أَنْ تَحْمِيَنِي مِنْ مَلَكِ الْمَوْتِ", "segs": null, "full_uz": "Meni o'lim farishtasidan himoya qilishingni.", "note": null},
  {"num": 291, "time": "00:20:42,900 --> 00:20:46,700", "arabic": "لَا أَقْدِرُ", "segs": null, "full_uz": "Bunga qudratim yetmaydi.", "note": null},
  {"num": 292, "time": "00:20:46,700 --> 00:20:50,519", "arabic": "أَنْ تُدْخِلَنِي الْجَنَّةَ وَتُبْعِدَنِي عَنِ النَّارِ", "segs": null, "full_uz": "Meni jannatga kiritib, do'zaxdan yiroqlashtirishingni.", "note": null},
  {"num": 293, "time": "00:20:50,519 --> 00:20:52,440", "arabic": "لَا أَقْوَى", "segs": null, "full_uz": "Bunga kuchim yetmaydi.", "note": null},
  {"num": 294, "time": "00:20:52,440 --> 00:20:55,720", "arabic": "فَاعْلَمْ إِذَنْ بِأَنَّكَ مَمْلُوكٌ وَلَسْتَ بِمَلِكٍ", "segs": null, "full_uz": "Bilib qo'y, demak, sen mamlukning o'zisan, podshoh emassan.", "note": null},
  {"num": 295, "time": "00:20:55,720 --> 00:20:58,240", "arabic": "وَلَا حَاجَةَ لِي فِي الْمَمَالِكِ", "segs": null, "full_uz": "Va menga podsholiklarning hojati yo'q.", "note": null},
  {"num": 296, "time": "00:21:16,700 --> 00:21:18,900", "arabic": "شَرَّفَتْ بِكَ الدَّارُ", "segs": null, "full_uz": "Siz bilan uy sharaflandi.", "note": null},
  {"num": 297, "time": "00:21:18,900 --> 00:21:21,100", "arabic": "اُنْظُرْ إِلَيْهَا مَا أَجْمَلَهَا", "segs": null, "full_uz": "Unga qarang, naqadar chiroyli.", "note": null},
  {"num": 298, "time": "00:21:21,100 --> 00:21:23,279", "arabic": "مَا زَالَتْ فِي رَيْعَانِ الشَّبَابِ", "segs": null, "full_uz": "Hali yoshlik gullab-yashnagan davrida.", "note": null},
  {"num": 299, "time": "00:21:23,279 --> 00:21:35,740", "arabic": "لَا تَلْمِسُونِي أَيُّهَا الرِّجَالُ", "segs": null, "full_uz": "Menga tegmanglar, ey erkaklar.", "note": null},
  {"num": 300, "time": "00:21:35,740 --> 00:21:37,900", "arabic": "مَنْ يَلْمِسُنِي سَأَقْتُلُهُ", "segs": null, "full_uz": "Menga tegadigan kishini o'ldiraman.", "note": null},
  {"num": 301, "time": "00:21:37,900 --> 00:21:40,380", "arabic": "لَنْ أَسْمَحَ لَكَ بِبَيْعِي أَبَدًا", "segs": null, "full_uz": "Sizga meni sotishga hech qachon ruxsat bermayman.", "note": null},
  {"num": 302, "time": "00:21:40,380 --> 00:21:42,680", "arabic": "لَنْ يَكُونَ لَكَ ذَلِكَ مَا حَيِيتُ", "segs": null, "full_uz": "Tirik ekanman, bu senga bo'lmaydi.", "note": null},
  {"num": 303, "time": "00:21:42,680 --> 00:21:44,140", "arabic": "خُذْهَا يَا حَنْظَلَةُ", "segs": null, "full_uz": "Uni olib ket, Hanzala.", "note": null},
  {"num": 304, "time": "00:21:44,140 --> 00:21:45,140", "arabic": "خُذْهَا", "segs": null, "full_uz": "Olib ket.", "note": null},
  {"num": 308, "time": "00:22:45,140 --> 00:22:58,300", "arabic": "أَتَنْتَظِرُ أَحَدًا يَا أَحْمَدُ؟", "segs": null, "full_uz": "Kimnidir kutyapsanmi, Ahmad?", "note": null},
  {"num": 309, "time": "00:22:58,300 --> 00:22:59,980", "arabic": "لَيْسَ عَلَى مَا أَذْكُرُ يَا أُمِّي", "segs": null, "full_uz": "Esimda yo'q, onajon.", "note": null},
  {"num": 310, "time": "00:22:59,980 --> 00:23:01,500", "arabic": "خَيْرًا إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, xayrli bo'lsin.", "note": null},
  {"num": 311, "time": "00:23:01,500 --> 00:23:06,000", "arabic": "أَهْلًا يَا مُحَمَّدُ", "segs": null, "full_uz": "Xush kelibsiz, Muhammad.", "note": null},
  {"num": 312, "time": "00:23:08,500 --> 00:23:09,840", "arabic": "اَلسَّلَامُ عَلَيْكُمْ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Assalomu alaykum, Ibn Hanbal.", "note": null},
  {"num": 313, "time": "00:23:09,840 --> 00:23:11,640", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ تَفَضَّلْ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin, marhamat.", "note": null},
  {"num": 314, "time": "00:23:11,640 --> 00:23:13,180", "arabic": "لَمْ آتِكَ زَائِرًا يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Sizga mehmon bo'lib kelmadim, Ibn Hanbal.", "note": null},
  {"num": 315, "time": "00:23:13,180 --> 00:23:15,660", "arabic": "وَإِنَّمَا أَحْمِلُ لَكَ خَبَرًا مُؤْسِفًا", "segs": null, "full_uz": "Balki sizga achinarli bir xabar olib keldim.", "note": null},
  {"num": 316, "time": "00:23:15,660 --> 00:23:17,500", "arabic": "لَا أَدْرِي إِنْ كُنْتَ سَمِعْتَهُ أَمْ لَا", "segs": null, "full_uz": "Buni eshitgan-eshitmaganingizni bilmayman.", "note": null},
  {"num": 317, "time": "00:23:17,500 --> 00:23:19,840", "arabic": "خَيْرًا يَا أَبَا الْمُغِيرَةِ", "segs": null, "full_uz": "Xayr bo'lsin, Abul-Mug'iyra.", "note": null},
  {"num": 318, "time": "00:23:19,840 --> 00:23:25,779", "arabic": "أَحْسَنَ اللَّهُ عَزَاءَكَ فِي شَيْخِنَا الْإِمَامِ أَبِي يُوسُفَ", "segs": null, "full_uz": "Alloh sizga ustozimiz imom Abu Yusuf haqidagi tasalliyingizni yaxshi qilsin.", "note": null},
  {"num": 319, "time": "00:23:25,779 --> 00:23:26,840", "arabic": "قَاضِي الْقُضَاةِ", "segs": null, "full_uz": "Bosh qozi.", "note": null},
  {"num": 320, "time": "00:23:26,840 --> 00:23:29,640", "arabic": "أَوَقَدْ مَاتَ؟", "segs": null, "full_uz": "Vafot etdimi?", "note": null},
  {"num": 321, "time": "00:23:29,640 --> 00:23:33,279", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "segs": null, "full_uz": "Albatta biz Allohnikimiz va albatta Unga qaytuvchimiz.", "note": null},
  {"num": 322, "time": "00:23:33,279 --> 00:23:35,900", "arabic": "لَقَدْ حَسِبْتُكَ قَدْ سَمِعْتَ", "segs": null, "full_uz": "Eshitgan bo'lsangiz kerak deb o'yladim.", "note": null},
  {"num": 323, "time": "00:23:35,900 --> 00:23:38,660", "arabic": "فَقَدْ نَعَوْهُ قَبْلَ قَلِيلٍ", "segs": null, "full_uz": "Uni yaqinda vafot etganini e'lon qilishdi.", "note": null},
  {"num": 324, "time": "00:23:38,660 --> 00:23:40,980", "arabic": "سَيُصَلِّي عَلَيْهِ أَمِيرُ الْمُؤْمِنِينَ هَارُونُ", "segs": null, "full_uz": "Unga mo'minlar amiri Horun janoza o'qiydi.", "note": null},
  {"num": 325, "time": "00:23:40,980 --> 00:23:43,160", "arabic": "وَيَدْفِنُونَهُ بَعْدَ الصَّلَاةِ", "segs": null, "full_uz": "Va namozdan keyin dafn qilishadi.", "note": null},
  {"num": 326, "time": "00:23:43,180 --> 00:23:45,740", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 327, "time": "00:23:45,740 --> 00:23:50,220", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "segs": null, "full_uz": "Albatta biz Allohnikimiz va albatta Unga qaytuvchimiz.", "note": null},
  {"num": 328, "time": "00:23:50,220 --> 00:24:06,039", "arabic": "سُبْحَانَ الْحَيِّ الَّذِي لَا يَمُوتُ", "segs": null, "full_uz": "Hech qachon o'lmaydigan Tirik Zot pokdir.", "note": null},
  {"num": 329, "time": "00:24:06,039 --> 00:24:11,740", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "segs": null, "full_uz": "Albatta biz Allohnikimiz va albatta Unga qaytuvchimiz.", "note": null},
  {"num": 331, "time": "00:24:43,180 --> 00:25:01,940", "arabic": "رَحِمَكَ اللَّهُ يَا أَبَا يُوسُفَ", "segs": null, "full_uz": "Alloh senga rahmat qilsin, Abu Yusuf.", "note": null},
  {"num": 332, "time": "00:25:01,940 --> 00:25:06,799", "arabic": "وَاللَّهِ إِنَّ فَقْدَكَ خَسَارَةٌ عَظِيمَةٌ لِلْمُسْلِمِينَ", "segs": null, "full_uz": "Alloh haqqi, seni yo'qotish musulmonlar uchun katta yo'qotishdir.", "note": null},
  {"num": 333, "time": "00:25:13,180 --> 00:25:32,080", "arabic": "لَوْلَا مَعُونَتُكَ يَا صَاحِبِي", "segs": null, "full_uz": "Yordaming bo'lmaganida, do'stim.", "note": null},
  {"num": 334, "time": "00:25:32,080 --> 00:25:36,720", "arabic": "لَمَا تَسَنَّى لِي أَنْ أَكُونَ فِي حَرَسِ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiri qorovullari safida bo'la olmasdim.", "note": null},
  {"num": 335, "time": "00:25:36,720 --> 00:25:39,440", "arabic": "نَحْنُ إِخْوَةٌ وَتَجْمَعُنَا صَدَاقَةٌ قَدِيمَةٌ", "segs": null, "full_uz": "Biz birodarmiz va bizni qadimiy do'stlik bog'laydi.", "note": null},
  {"num": 336, "time": "00:25:39,440 --> 00:25:43,940", "arabic": "أَنَا مَدِينٌ لَكَ يَا صَدِيقِي", "segs": null, "full_uz": "Men senga qarzdorman, do'stim.", "note": null},
  {"num": 337, "time": "00:25:43,940 --> 00:25:45,820", "arabic": "لَا تَقُلْ هَذَا يَا شَفِيعُ", "segs": null, "full_uz": "Bunday dema, Shafi'.", "note": null},
  {"num": 338, "time": "00:25:45,820 --> 00:25:48,480", "arabic": "أَعْتَذِرُ عَنِ انْقِطَاعِي عَنْ رُؤْيَتِكَ", "segs": null, "full_uz": "Seni ko'rishdan uzoq bo'lganim uchun uzr so'rayman.", "note": null},
  {"num": 339, "time": "00:25:48,480 --> 00:25:51,059", "arabic": "وَلَكِنْ هَذَا بِسَبَبِ طَبِيعَةِ عَمَلِنَا", "segs": null, "full_uz": "Lekin bu ishimiz tabiati sababli.", "note": null},
  {"num": 340, "time": "00:25:51,059 --> 00:25:55,059", "arabic": "وَلَوْلَا وَفَاةُ قَاضِي الْقُضَاةِ الْيَوْمَ لَمَا رَأَيْتُكَ يَا صَاحِبِي", "segs": null, "full_uz": "Agar bugun bosh qozi vafot etmaganida, seni ko'rmagan bo'lardim, do'stim.", "note": null},
  {"num": 341, "time": "00:25:55,059 --> 00:25:58,519", "arabic": "اَلْيَوْمَ مَسَاءً أَنْتَ عِنْدِي عَلَى الْعَشَاءِ", "segs": null, "full_uz": "Bugun kechqurun kechki ovqatga menikida bo'lasan.", "note": null},
  {"num": 342, "time": "00:25:58,519 --> 00:26:00,120", "arabic": "وَلَا أُرِيدُ أَعْذَارًا", "segs": null, "full_uz": "Va bahonalar eshitishni xohlamayman.", "note": null},
  {"num": 343, "time": "00:26:00,120 --> 00:26:03,039", "arabic": "إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa.", "note": null},
  {"num": 345, "time": "00:26:39,440 --> 00:26:54,660", "arabic": "لَا أُنْكِرُ أَنَّنِي تَتَلْمَذْتُ عَلَى يَدِ الشَّيْخِ أَبِي يُوسُفَ", "segs": null, "full_uz": "Shayx Abu Yusuf qo'lida tarbiya olganimni inkor etmayman.", "note": null},
  {"num": 346, "time": "00:26:54,660 --> 00:26:58,759", "arabic": "وَلَكِنْ ذَلِكَ لَا يَعْنِي أَنَّنِي أُوَافِقُهُ عَلَى كُلِّ أَفْكَارِهِ", "segs": null, "full_uz": "Lekin bu uning barcha fikrlariga qo'shilaman degani emas.", "note": null},
  {"num": 347, "time": "00:26:58,759 --> 00:27:03,140", "arabic": "وَمَا الَّذِي تَعِيبُهُ عَلَى أَبِي يُوسُفَ رَحِمَهُ اللَّهُ؟", "segs": null, "full_uz": "Abu Yusuf — Alloh unga rahmat qilsin — da nimani ayb deb bilasan?", "note": null},
  {"num": 348, "time": "00:27:03,140 --> 00:27:06,539", "arabic": "وَهُوَ قَاضِي الْقُضَاةِ الْإِمَامُ الْمُجْتَهِدُ", "segs": null, "full_uz": "Axir u bosh qozi, mujtahid imom edi.", "note": null},
  {"num": 349, "time": "00:27:06,539 --> 00:27:10,000", "arabic": "وَصَاحِبُ أَبِي حَنِيفَةَ النُّعْمَانِ إِمَامِ الْعِرَاقَيْنِ", "segs": null, "full_uz": "Va ikki Iroqning imomi Abu Hanifa an-Nu'monning safdoshi.", "note": null},
  {"num": 350, "time": "00:27:10,000 --> 00:27:15,279", "arabic": "قَبْلَ أَنْ أُخْبِرَكَ", "segs": null, "full_uz": "Senga aytishimdan oldin.", "note": null},
  {"num": 351, "time": "00:27:15,279 --> 00:27:18,420", "arabic": "أَلَا يَجْدُرُ بِنَا أَنْ نَتَعَارَفَ أَوَّلًا؟", "segs": null, "full_uz": "Avval tanishib olishimiz kerak emasmi?", "note": null},
  {"num": 352, "time": "00:27:18,420 --> 00:27:21,159", "arabic": "فَيَكُونَ الْحَدِيثُ وُدِّيًّا إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Toki suhbat, Alloh xohlasa, samimiy bo'lsin.", "note": null},
  {"num": 353, "time": "00:27:21,159 --> 00:27:23,579", "arabic": "أَنَا بِشْرٌ الْمَرِيسِيُّ", "segs": null, "full_uz": "Men Bishr al-Marisiyman.", "note": null},
  {"num": 354, "time": "00:27:23,579 --> 00:27:26,659", "arabic": "وَهَذَا صَاحِبِي ثُمَامَةُ بْنُ الْأَشْرَسِ", "segs": null, "full_uz": "Bu esa do'stim Sumoma ibn Ashras.", "note": null},
  {"num": 355, "time": "00:27:26,659 --> 00:27:29,659", "arabic": "وَأَنَا بَدْرٌ الْكِلَاعِيُّ", "segs": null, "full_uz": "Men esa Badr al-Kila'iyman.", "note": null},
  {"num": 356, "time": "00:27:29,659 --> 00:27:32,539", "arabic": "كَأَنَّكَ طَالِبُ عِلْمٍ يَا بَدْرُ", "segs": null, "full_uz": "Shekilli, sen ilm talabasisan, Badr.", "note": null},
  {"num": 357, "time": "00:27:32,539 --> 00:27:34,539", "arabic": "أَجَلْ وَالْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Ha, hamdlar bo'lsin.", "note": null},
  {"num": 358, "time": "00:27:34,539 --> 00:27:39,379", "arabic": "وَقَدْ أَكْرَمَنِي اللَّهُ بِالتَّلْمَذَةِ عَلَى يَدِ أَبِي يُوسُفَ الْقَاضِي رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Alloh meni qozi Abu Yusuf — Alloh unga rahmat qilsin — qo'lida shogird bo'lish sharafi bilan mukarram qildi.", "note": null},
  {"num": 359, "time": "00:27:39,379 --> 00:27:45,039", "arabic": "وَأَبِي مُعَاوِيَةَ هُشَيْمِ بْنِ بَشِيرٍ الْوَاسِطِيِّ رَحِمَهُ اللَّهُ وَغَيْرِهِمْ", "segs": null, "full_uz": "Va Abu Muoviya Hushaym ibn Bashir al-Vositiy — Alloh unga rahmat qilsin — va boshqalar qo'lida ham.", "note": null},
  {"num": 360, "time": "00:27:45,039 --> 00:27:47,799", "arabic": "سَعِدْتُ بِمَعْرِفَتِكَ يَا بَدْرُ", "segs": null, "full_uz": "Siz bilan tanishganimdan xursandman, Badr.", "note": null},
  {"num": 361, "time": "00:27:47,799 --> 00:27:54,079", "arabic": "مَا رَأْيُكَ أَنْ تَذْهَبَ مَعِي إِلَى دَارِي فَأُصْبِحَكَ كُلَّ مَا تُحِبُّ سَمَاعَهُ", "segs": null, "full_uz": "Men bilan uyimga borsang-u, eshitishni yaxshi ko'rgan hamma narsangni tonggacha aytib bersam, fikring qanday?", "note": null},
  {"num": 362, "time": "00:27:54,079 --> 00:27:56,039", "arabic": "وَلِمَ لَا", "segs": null, "full_uz": "Nega bo'lmasin.", "note": null},
  {"num": 363, "time": "00:27:56,039 --> 00:28:00,839", "arabic": "نَذْهَبُ وَنَرَى مَا أَخَذْتَ عَلَى أَبِي يُوسُفَ الْقَاضِي رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Boramiz va qozi Abu Yusuf — Alloh unga rahmat qilsin — ga nima da'vo qilganingizni ko'ramiz.", "note": null},
  {"num": 364, "time": "00:28:00,839 --> 00:28:02,079", "arabic": "رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Alloh unga rahmat qilsin.", "note": null},
  {"num": 365, "time": "00:28:02,079 --> 00:28:09,319", "arabic": "لِتَرْتَاحَ مِنْ أَحْمَدَ", "segs": null, "full_uz": "Ahmaddan qutulishing uchun.", "note": null},
  {"num": 366, "time": "00:28:09,319 --> 00:28:11,939", "arabic": "اِقْطَعْ عَلَيْهِ شِرْيَانَ حَيَاتِهِ", "segs": null, "full_uz": "Uning hayot tomirini kesib tashla.", "note": null},
  {"num": 367, "time": "00:28:11,939 --> 00:28:15,819", "arabic": "شِرْيَانَ حَيَاتِهِ؟", "segs": null, "full_uz": "Hayot tomirinimi?", "note": null},
  {"num": 368, "time": "00:28:15,819 --> 00:28:17,819", "arabic": "إِنِ اشْتَرَيْتَ مِنْهُ دُكَّانَهُ", "segs": null, "full_uz": "Agar do'konini undan sotib olsang.", "note": null},
  {"num": 369, "time": "00:28:17,819 --> 00:28:20,019", "arabic": "سَتَحْرِمُهُ مِنْ مَوْرِدِ رِزْقِهِ", "segs": null, "full_uz": "Uni rizq manbaidan mahrum qilasan.", "note": null},
  {"num": 370, "time": "00:28:20,019 --> 00:28:23,019", "arabic": "وَبَعْدَ أَنْ يُنْفِقَ الدَّرَاهِمَ ثَمَنَ الدُّكَّانِ", "segs": null, "full_uz": "Do'kon pulini sarflab bo'lgandan keyin.", "note": null},
  {"num": 371, "time": "00:28:23,019 --> 00:28:24,819", "arabic": "سَيُضْطَرُّ لِلْعَمَلِ", "segs": null, "full_uz": "Ishlashga majbur bo'ladi.", "note": null},
  {"num": 372, "time": "00:28:24,819 --> 00:28:26,899", "arabic": "وَيَنْصَرِفُ عَنْ طَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Va ilm talabidan chalg'iydi.", "note": null},
  {"num": 373, "time": "00:28:26,899 --> 00:28:29,319", "arabic": "وَتَصْفُو لَكَ حَلَقَاتُ الدَّرْسِ", "segs": null, "full_uz": "Va dars halqalari senga tinch-osoyishta qoladi.", "note": null},
  {"num": 374, "time": "00:28:29,319 --> 00:28:32,139", "arabic": "لِتَظْهَرَ فِيهَا تَمَيُّزُكَ وَاجْتِهَادُكَ", "segs": null, "full_uz": "Toki unda ustunliging va tirishqoqliging namoyon bo'lsin.", "note": null},
  {"num": 375, "time": "00:28:32,139 --> 00:28:35,899", "arabic": "فِكْرَةٌ رَائِعَةٌ هَذِهِ يَا شَفِيعُ", "segs": null, "full_uz": "Bu ajoyib fikr, Shafi'.", "note": null},
  {"num": 376, "time": "00:28:35,899 --> 00:28:39,259", "arabic": "وَهَذَا مَا سَأَفْعَلُهُ عَلَى الْفَوْرِ مِنَ الْغَدِ", "segs": null, "full_uz": "Ertagayoq shuni qilaman.", "note": null},
  {"num": 377, "time": "00:28:39,259 --> 00:28:42,000", "arabic": "لَكِنْ عَلَيْكَ أَنْ تَجِدَ أَحَدًا يَشْتَرِيَ لَكَ الدُّكَّانَ", "segs": null, "full_uz": "Lekin senga do'konni sotib olib beradigan kimnidir topishing kerak.", "note": null},
  {"num": 378, "time": "00:28:42,000 --> 00:28:45,759", "arabic": "لَا أَظُنُّ أَنَّ ابْنَ حَنْبَلٍ يَبِيعُكَ دُكَّانَهُ", "segs": null, "full_uz": "Ibn Hanbal do'konini senga sotadi deb o'ylamayman.", "note": null},
  {"num": 379, "time": "00:28:45,759 --> 00:28:48,980", "arabic": "وَفِي هَذِهِ أَيْضًا مَعَكَ الْحَقُّ", "segs": null, "full_uz": "Bunda ham haq sen tomondasan.", "note": null},
  {"num": 380, "time": "00:28:48,980 --> 00:28:51,559", "arabic": "شَفِيعُ", "segs": null, "full_uz": "Shafi'.", "note": null},
  {"num": 381, "time": "00:28:51,559 --> 00:28:53,379", "arabic": "يَا شَفِيعُ", "segs": null, "full_uz": "Ey Shafi'.", "note": null},
  {"num": 382, "time": "00:28:53,379 --> 00:28:54,859", "arabic": "يَا أَخِي", "segs": null, "full_uz": "Birodarim.", "note": null},
  {"num": 383, "time": "00:28:54,859 --> 00:28:56,279", "arabic": "شَفِيعُ", "segs": null, "full_uz": "Shafi'.", "note": null},
  {"num": 384, "time": "00:28:56,279 --> 00:29:03,899", "arabic": "لِمَاذَا لَا تَشْتَرِي جَارِيَةً تُسَاعِدُكَ فِي قَضَاءِ حَاجَاتِ أُخْتِكَ؟", "segs": null, "full_uz": "Nega singlingning ehtiyojlarida senga yordam beradigan bir cho'ri sotib olmaysan?", "note": null},
  {"num": 385, "time": "00:29:03,899 --> 00:29:05,399", "arabic": "هَذَا مَا سَأَفْعَلُهُ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, shuni qilaman.", "note": null},
  {"num": 386, "time": "00:29:26,279 --> 00:29:31,639", "arabic": "اِفْتَحِي الْبَابَ", "segs": null, "full_uz": "Eshikni och.", "note": null},
  {"num": 387, "time": "00:29:31,639 --> 00:29:35,000", "arabic": "اِفْتَحِي الْبَابَ يَا سَيِّدَتِي", "segs": null, "full_uz": "Eshikni oching, xonim.", "note": null},
  {"num": 388, "time": "00:29:35,000 --> 00:29:37,039", "arabic": "أُرِيدُ أَنْ أَقْضِيَ حَاجَةً", "segs": null, "full_uz": "Bir ehtiyojimni bajarishim kerak.", "note": null},
  {"num": 390, "time": "00:29:42,160 --> 00:29:45,619", "arabic": "أَلَا تَكْفِينَ عَنْ إِزْعَاجِي وَتَكْدِيرِ صَفْوِي؟", "segs": null, "full_uz": "Meni bezovta qilish va tinchimni buzishni bas qilmaysanmi?", "note": null},
  {"num": 391, "time": "00:29:45,619 --> 00:29:48,099", "arabic": "فَافْتَحِي", "segs": null, "full_uz": "Unda och.", "note": null},
  {"num": 392, "time": "00:29:48,099 --> 00:29:49,720", "arabic": "فَافْتَحِي الْبَابَ", "segs": null, "full_uz": "Eshikni och.", "note": null},
  {"num": 395, "time": "00:29:54,200 --> 00:30:18,200", "arabic": "هَلْ تُرِيدِينَ أَنْ أَكْسِرَ قَدَمَيْكِ حَتَّى تَكُفِّي عَنْ مُحَاوَلَاتِ الْهَرَبِ هَذِهِ؟", "segs": null, "full_uz": "Bu qochish urinishlaringni to'xtatishing uchun oyoqlaringni sindirib qo'yaymi?", "note": null},
  {"num": 396, "time": "00:30:18,200 --> 00:30:19,039", "arabic": "تَعَالِي", "segs": null, "full_uz": "Kel.", "note": null},
  {"num": 397, "time": "00:30:19,039 --> 00:30:22,840", "arabic": "اُتْرُكِينِي اُتْرُكِينِي أُرِيدُ أَنْ أَرْحَلَ مِنْ هُنَا", "segs": null, "full_uz": "Qo'yib yubor, qo'yib yubor, bu yerdan ketmoqchiman.", "note": null},
  {"num": 399, "time": "00:30:26,839 --> 00:30:28,839", "arabic": "لَا عَلَيْكِ", "segs": null, "full_uz": "Xavotir olma.", "note": null},
  {"num": 401, "time": "00:30:48,839 --> 00:30:51,839", "arabic": "أَنَا خَارِجٌ يَا أُمِّي، هَلْ لَكِ حَاجَةٌ أَقْضِيهَا؟", "segs": null, "full_uz": "Men chiqyapman, onajon, bajaradigan biror ishingiz bormi?", "note": null},
  {"num": 402, "time": "00:30:51,839 --> 00:30:53,000", "arabic": "إِلَى حَلْقَةِ الدَّرْسِ؟", "segs": null, "full_uz": "Dars halqasigami?", "note": null},
  {"num": 403, "time": "00:30:53,000 --> 00:30:53,319", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 404, "time": "00:30:53,319 --> 00:30:56,699", "arabic": "سَهَّلَ اللَّهُ لَكَ طَرِيقًا إِلَى الْجَنَّةِ يَا وَلَدِي", "segs": null, "full_uz": "Alloh senga jannatga yo'lni osonlashtirsin, o'g'lim.", "note": null},
  {"num": 405, "time": "00:30:56,699 --> 00:30:58,119", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 406, "time": "00:30:58,119 --> 00:31:00,379", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 407, "time": "00:31:00,379 --> 00:31:01,399", "arabic": "أَحْمَدُ", "segs": null, "full_uz": "Ahmad.", "note": null},
  {"num": 408, "time": "00:31:01,399 --> 00:31:03,699", "arabic": "لَبَّيْكِ يَا أُمِّي", "segs": null, "full_uz": "Labbay, onajon.", "note": null},
  {"num": 409, "time": "00:31:03,699 --> 00:31:09,659", "arabic": "إِذَا رَأَيْتَ أَنْ تَمُرَّ عَلَى عَامِرٍ الْإِسْكَافِيِّ بَعْدَ انْتِهَائِكَ مِنْ دَرْسِكَ", "segs": null, "full_uz": "Darsingdan bo'shagach, agar mumkin bo'lsa, etikdo'z Omirning oldiga o'tib o'tsang.", "note": null},
  {"num": 410, "time": "00:31:09,659 --> 00:31:14,599", "arabic": "أَوْشَكَ هِلَالُ الشَّهْرِ الثَّالِثِ عَلَى الْمَغِيبِ وَلَمْ يَدْفَعْ أُجْرَةَ الدُّكَّانِ بَعْدُ", "segs": null, "full_uz": "Uchinchi oyning yangi oyi botishga yaqinlashib qoldi-yu, u hali do'kon ijarasini to'lamadi.", "note": null},
  {"num": 411, "time": "00:31:14,599 --> 00:31:15,699", "arabic": "أَفْعَلُ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, shunday qilaman.", "note": null},
  {"num": 412, "time": "00:31:15,699 --> 00:31:16,899", "arabic": "شَيْءٌ آخَرُ؟", "segs": null, "full_uz": "Boshqa narsa bormi?", "note": null},
  {"num": 413, "time": "00:31:16,899 --> 00:31:20,039", "arabic": "لَا أَدْرِي لِمَاذَا يُصِرُّ عَلَى التَّأْخِيرِ فِي دَفْعِ إِجَارَةِ الدُّكَّانِ", "segs": null, "full_uz": "Nega u do'kon ijarasini to'lashda qat'iy kechiktirishda davom etayotganini bilmayman.", "note": null},
  {"num": 414, "time": "00:31:20,039 --> 00:31:23,220", "arabic": "رَغْمَ أَنَّهَا تُعِينُنَا عَلَى نَفَقَةِ مَعِيشَتِنَا", "segs": null, "full_uz": "Holbuki, u bizga turmush xarajatlarimizda yordam beradi.", "note": null},
  {"num": 415, "time": "00:31:23,220 --> 00:31:26,099", "arabic": "لَعَلَّهُ فِي حَاجَةٍ", "segs": null, "full_uz": "Balki u muhtojdir.", "note": null},
  {"num": 416, "time": "00:31:26,099 --> 00:31:28,039", "arabic": "كَانَ اللَّهُ فِي عَوْنِ الْخَلْقِ", "segs": null, "full_uz": "Alloh xalqqa yordamchi bo'lsin.", "note": null},
  {"num": 417, "time": "00:31:28,700 --> 00:31:30,839", "arabic": "وَنَحْنُ أَيْضًا كَانَ اللَّهُ فِي عَوْنِنَا", "segs": null, "full_uz": "Bizga ham Alloh yordamchi bo'lsin.", "note": null},
  {"num": 418, "time": "00:31:30,839 --> 00:31:34,359", "arabic": "طَالَمَا أَنَّ الدُّكَّانَ تَدُرُّ عَلَيْهِ رِزْقًا مُنَاسِبًا", "segs": null, "full_uz": "Do'kon unga munosib rizq keltirar ekan.", "note": null},
  {"num": 419, "time": "00:31:34,359 --> 00:31:36,200", "arabic": "فَلِمَ يَتَأَخَّرُ فِي الدَّفْعِ؟", "segs": null, "full_uz": "Unda nega to'lashda kechikadi?", "note": null},
  {"num": 420, "time": "00:31:36,200 --> 00:31:36,779", "arabic": "لَا تَقْلَقِي", "segs": null, "full_uz": "Xavotir olmang.", "note": null},
  {"num": 421, "time": "00:31:36,779 --> 00:31:39,139", "arabic": "سَأَرَاهُ وَأَرَى مَا وَرَاءَهُ", "segs": null, "full_uz": "Uni ko'rib, sababini bilib olaman.", "note": null},
  {"num": 422, "time": "00:31:39,139 --> 00:31:40,000", "arabic": "ائْذَنِي لِي الْآنَ", "segs": null, "full_uz": "Endi menga ijozat bering.", "note": null},
  {"num": 423, "time": "00:31:40,000 --> 00:31:42,279", "arabic": "بِحِفْظِ اللَّهِ وَرِعَايَتِهِ يَا وَلَدِي", "segs": null, "full_uz": "Allohning saqlash va himoyasi ostida bo'l, o'g'lim.", "note": null},
  {"num": 424, "time": "00:31:42,279 --> 00:31:49,399", "arabic": "زَادَكَ اللَّهُ عِلْمًا فِي الدِّينِ", "segs": null, "full_uz": "Alloh dinda ilmingni ziyoda qilsin.", "note": null},
  {"num": 425, "time": "00:31:50,039 --> 00:31:51,799", "arabic": "وَزُهْدًا فِي الدُّنْيَا", "segs": null, "full_uz": "Va dunyoda zohidlikni.", "note": null},
  {"num": 426, "time": "00:31:51,799 --> 00:31:55,159", "arabic": "وَغِنًى عَمَّا فِي أَيْدِي النَّاسِ", "segs": null, "full_uz": "Va odamlarning qo'lidagi narsalardan behojatlikni ato etsin.", "note": null},
  {"num": 427, "time": "00:31:55,159 --> 00:31:57,680", "arabic": "اَللَّهُمَّ آمِينَ", "segs": null, "full_uz": "Ey Alloh, omin.", "note": null},
  {"num": 428, "time": "00:31:57,680 --> 00:31:58,819", "arabic": "آمِينَ", "segs": null, "full_uz": "Omin.", "note": null},
  {"num": 429, "time": "00:31:58,819 --> 00:32:11,720", "arabic": "لَا تَظُنَّ أَنَّ مِهْنَةَ الْإِسْكَافِيِّ تَقِلُّ خَطَرًا عَنْ أَيِّ مِهْنَةٍ أُخْرَى", "segs": null, "full_uz": "Etikdo'zlik kasbi boshqa har qanday kasbdan ahamiyati kam deb o'ylama.", "note": null},
  {"num": 430, "time": "00:32:11,720 --> 00:32:16,139", "arabic": "اَلْإِسْكَافِيُّ لَا يَقِلُّ شَأْنًا عَنِ الْوَالِي نَفْسِهِ", "segs": null, "full_uz": "Etikdo'z hokimning o'zidan qadr-qimmatda kam emas.", "note": null},
  {"num": 431, "time": "00:32:16,139 --> 00:32:19,099", "arabic": "لَوْلَا الْإِسْكَافِيُّ لَكَانَ نِصْفُ النَّاسِ حُفَاةً", "segs": null, "full_uz": "Etikdo'z bo'lmaganida, odamlarning yarmi yalangoyoq bo'lardi.", "note": null},
  {"num": 432, "time": "00:32:19,099 --> 00:32:20,879", "arabic": "بَلْ أَكْثَرُ مِنَ النِّصْفِ", "segs": null, "full_uz": "Balki yarmidan ko'prog'i.", "note": null},
  {"num": 433, "time": "00:32:20,879 --> 00:32:24,339", "arabic": "لَوْلَا الْإِسْكَافِيُّ لَكَانَتِ الْأُمُورُ صَعْبَةً جِدًّا", "segs": null, "full_uz": "Etikdo'z bo'lmaganida, ishlar juda qiyin bo'lardi.", "note": null},
  {"num": 434, "time": "00:32:24,339 --> 00:32:29,099", "arabic": "مَا السَّبَبُ إِذَنْ فِي أَنَّ نِصْفَ النَّاسِ حُفَاةٌ كَمَا تَرَى؟", "segs": null, "full_uz": "Unda ko'rib turganingizdek, odamlarning yarmi yalangoyoq bo'lishining sababi nima?", "note": null},
  {"num": 435, "time": "00:32:29,819 --> 00:32:34,099", "arabic": "رُبَّمَا كَانَ ذَلِكَ بِسَبَبِ الْفَقْرِ الَّذِي يُعَانِيهِ النَّاسُ فِي هَذِهِ الدَّوْلَةِ", "segs": null, "full_uz": "Balki bu davlatdagi odamlar boshdan kechirayotgan qashshoqlik sababidandir.", "note": null},
  {"num": 436, "time": "00:32:34,980 --> 00:32:40,919", "arabic": "وَمَا شَأْنُ الدَّوْلَةِ فِي كَوْنِ النَّاسِ حُفَاةً", "segs": null, "full_uz": "Odamlarning yalangoyoqligiga davlatning nima aloqasi bor?", "note": null},
  {"num": 437, "time": "00:32:40,919 --> 00:32:44,779", "arabic": "لَوْ لَمْ يَظْلِمِ الْوُلَاةُ وَيَسْرِقُوا أَمْوَالَهُمْ", "segs": null, "full_uz": "Agar hokimlar zulm qilmasa va ularning pullarini o'g'irlamasa.", "note": null},
  {"num": 438, "time": "00:32:44,779 --> 00:32:46,579", "arabic": "لَكَانَ النَّاسُ أَحْسَنَ حَالًا", "segs": null, "full_uz": "Odamlar yaxshiroq ahvolda bo'lardi.", "note": null},
  {"num": 439, "time": "00:32:46,579 --> 00:32:49,759", "arabic": "وَلَمَا أَصْبَحَ نِصْفُ النَّاسِ حُفَاةً كَمَا تَقُولُ", "segs": null, "full_uz": "Va aytganingizdek, odamlarning yarmi yalangoyoq bo'lib qolmasdi.", "note": null},
  {"num": 440, "time": "00:32:49,759 --> 00:32:55,539", "arabic": "اِسْمَعَا أَيُّهَا الرَّجُلَانِ", "segs": null, "full_uz": "Eshitinglar, ikkovingiz.", "note": null},
  {"num": 441, "time": "00:32:55,539 --> 00:32:58,220", "arabic": "أَنَا لَمْ أَقْصِدْ مَا تَقُولَانِهِ", "segs": null, "full_uz": "Men aytayotgan narsangizni nazarda tutmagandim.", "note": null},
  {"num": 442, "time": "00:32:58,220 --> 00:33:01,559", "arabic": "نَحْنُ بِخَيْرٍ وَالْحَمْدُ لِلَّهِ وَلَا يَنْقُصُنَا شَيْءٌ", "segs": null, "full_uz": "Biz yaxshimiz, hamdlar bo'lsin, hech narsamiz kam emas.", "note": null},
  {"num": 443, "time": "00:33:01,559 --> 00:33:04,699", "arabic": "أَنَا أُحَدِّثُكُمْ عَنِ الْأَحْذِيَةِ تُحَدِّثَانِنِي عَنِ الْوُلَاةِ", "segs": null, "full_uz": "Men sizlarga poyabzallar haqida gapiryapman, sizlar esa menga hokimlar haqida gapiryapsizlar.", "note": null},
  {"num": 444, "time": "00:33:04,699 --> 00:33:06,579", "arabic": "يَا لَهُ مِنْ كَلَامٍ أَحْمَقَ كَلَامُكُمَا", "segs": null, "full_uz": "Gaplaringiz naqadar ahmoqona!", "note": null},
  {"num": 445, "time": "00:33:06,579 --> 00:33:13,099", "arabic": "أَلَمْ تَقُلْ أَنْتَ إِنَّ الْإِسْكَافِيَّ لَا يَقِلُّ شَأْنًا عَنِ الْوَالِي", "segs": null, "full_uz": "Sen o'zing etikdo'z hokimdan kam emas demaganmiding?", "note": null},
  {"num": 446, "time": "00:33:13,099 --> 00:33:14,439", "arabic": "أَلَمْ تَقُلْ ذَلِكَ", "segs": null, "full_uz": "Shuni aytmaganmiding?", "note": null},
  {"num": 447, "time": "00:33:14,440 --> 00:33:16,480", "arabic": "أَنَا لَا أَذْكُرُ شَيْئًا مِمَّا قُلْتُ", "segs": null, "full_uz": "Aytgan gapimdan hech narsa esimda yo'q.", "note": null},
  {"num": 448, "time": "00:33:16,480 --> 00:33:19,180", "arabic": "أَنَا أَحْيَانًا أَهْذِي بِأَشْيَاءَ أَنَا نَفْسِي لَا أَفْهَمُهَا", "segs": null, "full_uz": "Ba'zan o'zim tushunmaydigan narsalar haqida bidirlab yuboraman.", "note": null},
  {"num": 449, "time": "00:33:19,180 --> 00:33:20,600", "arabic": "مَا شَأْنِي أَنَا وَالْوُلَاةِ", "segs": null, "full_uz": "Mening hokimlar bilan nima ishim bor?", "note": null},
  {"num": 450, "time": "00:33:20,600 --> 00:33:23,140", "arabic": "مَا أَنَا إِلَّا إِسْكَافِيٌّ يُصْلِحُ أَحْذِيَةَ النَّاسِ", "segs": null, "full_uz": "Men faqat odamlarning poyabzalini tuzatuvchi etikdo'zman, xolos.", "note": null},
  {"num": 451, "time": "00:33:23,140 --> 00:33:26,580", "arabic": "لَا بُدَّ أَنَّ أَمِيرَ الْمُؤْمِنِينَ هَذَا ظَالِمٌ", "segs": null, "full_uz": "Shubhasiz, bu mo'minlar amiri zolim.", "note": null},
  {"num": 452, "time": "00:33:26,580 --> 00:33:29,500", "arabic": "حَتَّى جَعَلَ النَّاسَ يَخْشَوْنَ وُلَاتَهُ", "segs": null, "full_uz": "Hatto odamlarni o'z hokimlaridan qo'rqadigan qilib qo'ygan.", "note": null},
  {"num": 453, "time": "00:33:29,500 --> 00:33:32,519", "arabic": "هَيَّا انْصَرِفَا", "segs": null, "full_uz": "Yur, ikkovingiz keting.", "note": null},
  {"num": 454, "time": "00:33:32,519 --> 00:33:34,180", "arabic": "خُذَا نَعْلًا وَانْصَرِفَا", "segs": null, "full_uz": "Bir juft poyabzal olib, ketinglar.", "note": null},
  {"num": 455, "time": "00:33:34,180 --> 00:33:35,640", "arabic": "لَا أُرِيدُ إِجْرَةَ إِصْلَاحِهَا", "segs": null, "full_uz": "Uni ta'mirlash haqini xohlamayman.", "note": null},
  {"num": 456, "time": "00:33:35,640 --> 00:33:39,740", "arabic": "وَقَى اللَّهُ شَرَّ كَلَامِكُمَا وَشَرَّ مَنْ يَتَحَسَّسُ أَخْبَارَنَا", "segs": null, "full_uz": "Alloh sizlarning gapingiz yovuzligidan va xabarlarimizni izlab yuruvchilarning yovuzligidan asrasin.", "note": null},
  {"num": 457, "time": "00:33:39,740 --> 00:33:40,740", "arabic": "هَيَّا انْصَرِفَا", "segs": null, "full_uz": "Yur, ikkovingiz keting.", "note": null},
  {"num": 461, "time": "00:35:14,440 --> 00:35:23,260", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 462, "time": "00:35:23,260 --> 00:35:26,380", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 463, "time": "00:35:26,380 --> 00:35:28,659", "arabic": "كَيْفَ كَانَ يَوْمُكَ يَا وَلَدِي؟", "segs": null, "full_uz": "Kuning qanday o'tdi, o'g'lim?", "note": null},
  {"num": 464, "time": "00:35:28,659 --> 00:35:29,440", "arabic": "اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Hamdlar bo'lsin.", "note": null},
  {"num": 465, "time": "00:35:29,440 --> 00:35:31,619", "arabic": "هَلْ عَرَجْتَ عَلَى عَامِرٍ الْإِسْكَافِيِّ؟", "segs": null, "full_uz": "Etikdo'z Omirning oldiga o'tdingmi?", "note": null},
  {"num": 466, "time": "00:35:31,619 --> 00:35:31,980", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 467, "time": "00:35:31,980 --> 00:35:35,440", "arabic": "وَهَلْ حَدَّثْتَهُ بِشَأْنِ كِرَاءِ الدُّكَّانِ؟", "segs": null, "full_uz": "Do'kon ijarasi haqida u bilan gaplashdingmi?", "note": null},
  {"num": 468, "time": "00:35:36,260 --> 00:35:37,440", "arabic": "فِي الْحَقِيقَةِ لَا يَا أُمِّي", "segs": null, "full_uz": "Rostini aytsam, yo'q, onajon.", "note": null},
  {"num": 469, "time": "00:35:38,000 --> 00:35:38,440", "arabic": "لِمَاذَا؟", "segs": null, "full_uz": "Nega?", "note": null},
  {"num": 470, "time": "00:35:39,360 --> 00:35:42,940", "arabic": "مَا إِنْ بَدَأْتُهُ بِالسُّؤَالِ عَنْ حَالِهِ حَتَّى ابْتَدَرَنِي بِالشَّكْوَى وَالْأَعْذَارِ", "segs": null, "full_uz": "Uning ahvolidan so'rashni boshlashim bilanoq, u shikoyat va bahonalar bilan meni to'xtatdi.", "note": null},
  {"num": 471, "time": "00:35:42,940 --> 00:35:44,079", "arabic": "فَأَعْرَضْتُ عَنْ ذَلِكَ", "segs": null, "full_uz": "Shu sababdan bu haqda gapirmadim.", "note": null},
  {"num": 472, "time": "00:35:44,079 --> 00:35:47,259", "arabic": "يَبْدُو أَنَّ الرَّجُلَ تُثْقِلُهُ هُمُومُ الْحَيَاةِ كَغَيْرِهِ", "segs": null, "full_uz": "Ko'rinishidan, u kishini ham boshqalar kabi turmush tashvishlari ezib turibdi.", "note": null},
  {"num": 473, "time": "00:35:47,259 --> 00:35:50,279", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 474, "time": "00:35:50,279 --> 00:35:53,539", "arabic": "دَعْنِي أُحْضِرْ لَكَ الطَّعَامَ إِذَنْ", "segs": null, "full_uz": "Unda senga ovqat olib kelay.", "note": null},
  {"num": 475, "time": "00:35:53,539 --> 00:35:56,079", "arabic": "لَا حَاجَةَ لِي فِي الطَّعَامِ فَأَنَا صَائِمٌ وَالْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Ovqatga hojatim yo'q, ro'zadorman, hamdlar bo'lsin.", "note": null},
  {"num": 476, "time": "00:35:56,619 --> 00:35:57,880", "arabic": "اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Hamdlar bo'lsin.", "note": null},
  {"num": 477, "time": "00:35:57,880 --> 00:36:02,079", "arabic": "تَقَبَّلَ اللَّهُ صِيَامَكَ وَزَادَكَ عِلْمًا وَأَدَبًا", "segs": null, "full_uz": "Alloh ro'zangni qabul qilsin va ilm hamda odobingni ziyoda qilsin.", "note": null},
  {"num": 478, "time": "00:36:02,900 --> 00:36:04,799", "arabic": "يَا رَبِّ", "segs": null, "full_uz": "Ey Robbim.", "note": null},
  {"num": 479, "time": "00:36:04,799 --> 00:36:08,079", "arabic": "أَلَمْ تَنْتَهِي مِنْ حِيَاكَةِ تِلْكَ السَّجَّادَةِ؟", "segs": null, "full_uz": "O'sha gilamni to'qishni tugatmadingmi?", "note": null},
  {"num": 480, "time": "00:36:08,759 --> 00:36:10,079", "arabic": "لَمْ يَبْقَ مِنْهَا إِلَّا الْقَلِيلُ", "segs": null, "full_uz": "Undan faqat ozgina qoldi.", "note": null},
  {"num": 481, "time": "00:36:10,079 --> 00:36:14,500", "arabic": "يَا أُمَّاهُ أَلَمْ تَعِدِينِي بِأَنَّكِ سَتَتَوَقَّفِينَ عَنِ الْعَمَلِ؟", "segs": null, "full_uz": "Onajon, ishlashni to'xtatishga va'da bermagan edingizmi?", "note": null},
  {"num": 482, "time": "00:36:14,500 --> 00:36:19,900", "arabic": "قُلْتُ لَكِ دَعِي النَّفَقَةَ عَلَيَّ فَأَنَا الرَّجُلُ فِي هَذَا الْبَيْتِ وَأَنَا مَنْ يَهْتَمُّ فِي شُؤُونِهِ", "segs": [{"ar": "قُلْتُ لَكِ دَعِي النَّفَقَةَ عَلَيَّ", "uz": "senga aytdim-ku, xarajatni menga qoldir"}, {"ar": "فَأَنَا الرَّجُلُ فِي هَذَا الْبَيْتِ وَأَنَا مَنْ يَهْتَمُّ فِي شُؤُونِهِ", "uz": "bu uyning erkagi menman va uning ishlariga men g'amxo'rlik qilaman"}], "full_uz": "Senga aytdim-ku, xarajatni menga qoldir, bu uyning erkagi menman va uning ishlariga men g'amxo'rlik qilaman.", "note": null},
  {"num": 483, "time": "00:36:19,900 --> 00:36:20,759", "arabic": "أَحْمَدُ", "segs": null, "full_uz": "Ahmad.", "note": null},
  {"num": 484, "time": "00:36:20,759 --> 00:36:25,960", "arabic": "أَلَمْ نَتَّفِقْ عَلَى عَدَمِ الْحَدِيثِ فِي هَذَا الْأَمْرِ؟", "segs": null, "full_uz": "Bu masalada gaplashmaslikka kelishmaganmidik?", "note": null},
  {"num": 485, "time": "00:36:25,960 --> 00:36:29,019", "arabic": "قُلْتُ لَكَ إِنَّهَا تَمْلَأُ وَقْتِي", "segs": null, "full_uz": "Senga aytdim-ku, u vaqtimni to'ldiradi.", "note": null},
  {"num": 486, "time": "00:36:29,019 --> 00:36:37,639", "arabic": "لِمَ أَنْتَ سَاكِتٌ هَكَذَا؟", "segs": null, "full_uz": "Nega bunday jim turibsan?", "note": null},
  {"num": 487, "time": "00:36:40,079 --> 00:36:42,139", "arabic": "لَا أَقْوَى عَلَى مُحَاجَّتِكِ يَا أُمِّي", "segs": null, "full_uz": "Sizga bahslashishga kuchim yetmaydi, onajon.", "note": null},
  {"num": 488, "time": "00:36:42,139 --> 00:36:45,980", "arabic": "فَأَنَا لَا أَقْبَلُ أَنْ تُتْعِبَ الْأُمُّ نَفْسَهَا لِيَرْتَاحَ وَلَدُهَا", "segs": null, "full_uz": "Men ona o'zini charchatib, o'g'li rohat qilishiga rozi emasman.", "note": null},
  {"num": 489, "time": "00:36:45,980 --> 00:36:48,840", "arabic": "وَهَلْ فِي طَلَبِ الْعِلْمِ رَاحَةٌ يَا بُنَيَّ؟", "segs": null, "full_uz": "Ilm talab qilishda dam olish bo'ladimi, o'g'lim?", "note": null},
  {"num": 490, "time": "00:36:48,840 --> 00:36:53,079", "arabic": "أَلَمْ تَسْمَعْ أَنَّهُ تَسْتَغْفِرُ لَهُ الْمَلَائِكَةُ وَالْحِيتَانُ فِي الْبَحْرِ؟", "segs": null, "full_uz": "Farishtalar va dengizdagi baliqlar u uchun mag'firat so'rashini eshitmaganmisan?", "note": "Ilm talabasi haqidagi mashhur hadisga ishora."},
  {"num": 491, "time": "00:36:53,980 --> 00:36:55,759", "arabic": "رَاحَتِي فِي سَعَادَتِكَ يَا بُنَيَّ", "segs": null, "full_uz": "Mening rohatim — sening baxting, o'g'lim.", "note": null},
  {"num": 492, "time": "00:36:55,759 --> 00:36:59,059", "arabic": "فَأَنْتَ لَا تَعْرِفُ كَمْ أَشْعُرُ بِهِ مِنْ سَعَادَةٍ", "segs": null, "full_uz": "Qanchalik baxtli his qilishimni bilmaysan.", "note": null},
  {"num": 493, "time": "00:36:59,059 --> 00:37:02,239", "arabic": "عِنْدَمَا أَرَاكَ تَحْمِلُ قَرَاطِيسَكَ وَمِحْبَرَتَكَ", "segs": null, "full_uz": "Seni qog'ozlaring va siyohdoningni ko'targan holda ko'rganimda.", "note": null},
  {"num": 494, "time": "00:37:10,079 --> 00:37:13,880", "arabic": "يَا امْرَأَةُ", "segs": null, "full_uz": "Ey ayol.", "note": null},
  {"num": 495, "time": "00:37:13,880 --> 00:37:29,960", "arabic": "أَتَعْرِفِينَ الْقِرَاءَةَ؟", "segs": null, "full_uz": "O'qishni bilasanmi?", "note": null},
  {"num": 496, "time": "00:37:29,960 --> 00:37:33,559", "arabic": "لَا عَلَيْكَ يَا أَخِي", "segs": null, "full_uz": "Xavotir olmang, birodarim.", "note": null},
  {"num": 497, "time": "00:37:33,559 --> 00:37:37,000", "arabic": "قُلْتُ أَتَعْرِفِينَ الْقِرَاءَةَ؟", "segs": null, "full_uz": "O'qishni bilasanmi, dedim.", "note": null},
  {"num": 498, "time": "00:37:37,000 --> 00:37:37,480", "arabic": "لَا لَا", "segs": null, "full_uz": "Yo'q, yo'q.", "note": null},
  {"num": 499, "time": "00:37:37,480 --> 00:37:40,659", "arabic": "أَلَكِ زَوْجٌ يَقْرَأُ الْقُرْآنَ؟", "segs": null, "full_uz": "Qur'on o'qiydigan eringiz bormi?", "note": null},
  {"num": 500, "time": "00:37:40,659 --> 00:37:41,880", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 501, "time": "00:37:41,880 --> 00:37:45,019", "arabic": "أَلَكِ وَلَدٌ يَقْرَأُ الْقُرْآنَ؟", "segs": null, "full_uz": "Qur'on o'qiydigan o'g'lingiz bormi?", "note": null},
  {"num": 502, "time": "00:37:45,019 --> 00:37:45,920", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 503, "time": "00:37:45,920 --> 00:37:50,320", "arabic": "لَا أَحَدَ فِي بَيْتِكُمْ يَقْرَأُ الْقُرْآنَ؟", "segs": null, "full_uz": "Uyingizda hech kim Qur'on o'qimaydimi?", "note": null},
  {"num": 504, "time": "00:37:50,320 --> 00:37:51,440", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 505, "time": "00:37:51,440 --> 00:37:55,760", "arabic": "اَللَّهُمَّ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ", "segs": null, "full_uz": "Ey Alloh, kuch-quvvat faqat Ulug' va Oliy Alloh bilandir.", "note": null},
  {"num": 506, "time": "00:37:55,760 --> 00:38:00,340", "arabic": "بَيْتٌ مِنْ بُيُوتِ الْمُسْلِمِينَ وَلَا يَقْرَأُ أَحَدٌ فِيهِ الْقُرْآنَ", "segs": null, "full_uz": "Musulmonlar uyidan biri-yu, unda hech kim Qur'on o'qimaydi.", "note": null},
  {"num": 507, "time": "00:38:00,340 --> 00:38:06,760", "arabic": "مَا رَأْيُكِ إِذَنْ أَنْ تُرْجِعِي الْمُصْحَفَ إِلَى مَنْ يَعْرِفُ الْقِرَاءَةَ", "segs": null, "full_uz": "Unda mushafni o'qishni biladigan kishiga qaytarsangiz-chi?", "note": null},
  {"num": 508, "time": "00:38:07,480 --> 00:38:10,400", "arabic": "وَتَحْتَفِظِي أَنْتِ بِالْجُبَّةِ لِنَفْسِكِ", "segs": null, "full_uz": "Va jubbani o'zingizga saqlab qolasiz.", "note": null},
  {"num": 509, "time": "00:38:10,400 --> 00:38:14,240", "arabic": "لَا أُرِيدُ مِنْكَ شَيْئًا إِلَّا أَنْ تَغْفِرَ لِي", "segs": null, "full_uz": "Sizdan faqat meni kechirishingizni xohlayman.", "note": null},
  {"num": 510, "time": "00:38:14,240 --> 00:38:22,000", "arabic": "سَامَحَكَ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ", "segs": null, "full_uz": "Alloh sizni dunyo va oxiratda kechirsin.", "note": null},
  {"num": 511, "time": "00:38:22,000 --> 00:38:27,320", "arabic": "وَلَوْ كَانَ مَعْرُوفٌ يَمْلِكُ غَيْرَهُ لَأَعْطَاكِ", "segs": null, "full_uz": "Agar Ma'rufning boshqa narsasi bo'lganida, sizga berardi.", "note": null},
  {"num": 512, "time": "00:38:37,480 --> 00:38:42,139", "arabic": "أَنْتَ الْقَوِيُّ وَنَحْنُ الضُّعَفَاءُ", "segs": null, "full_uz": "Sen kuchlisan, biz esa ojizmiz.", "note": null},
  {"num": 513, "time": "00:38:42,139 --> 00:38:46,079", "arabic": "أَنْتَ الْغَفُورُ وَنَحْنُ الْأَذِلَّاءُ", "segs": null, "full_uz": "Sen mag'firat qiluvchisan, biz esa xor-zorlarmiz.", "note": null},
  {"num": 514, "time": "00:38:46,079 --> 00:38:48,340", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ", "segs": null, "full_uz": "Allohdan o'zga iloh yo'q.", "note": null},
  {"num": 515, "time": "00:38:48,340 --> 00:39:00,740", "arabic": "وَلِمَ لَا تَعْرِضُ عَلَيْهِ ذَلِكَ بِنَفْسِكَ يَا صُهَيْبُ؟", "segs": null, "full_uz": "Nega buni o'zing taklif qilmaysan unga, Suhayb?", "note": null},
  {"num": 516, "time": "00:39:00,740 --> 00:39:03,039", "arabic": "أَنْتَ تَعْلَمُ سُوءَ عَلَاقَتِي بِابْنِ حَنْبَلٍ", "segs": null, "full_uz": "Ibn Hanbal bilan munosabatim yomonligini bilasan.", "note": null},
  {"num": 517, "time": "00:39:03,039 --> 00:39:06,340", "arabic": "وَأَخْشَى إِنْ عَرَضْتُ عَلَيْهِ شِرَاءَ دُكَّانِهِ", "segs": null, "full_uz": "Va agar do'konini sotib olishni taklif qilsam.", "note": null},
  {"num": 518, "time": "00:39:06,340 --> 00:39:09,559", "arabic": "أَنْ يَرْفُضَ كَرْهًا لِي لَا امْتِنَاعًا عَنْ بَيْعِهِ", "segs": null, "full_uz": "Sotishdan bosh tortgani uchun emas, menga bo'lgan nafrati tufayli rad etishidan qo'rqaman.", "note": null},
  {"num": 519, "time": "00:39:09,559 --> 00:39:14,340", "arabic": "فَقُلْتُ لَوْ أَنَّكَ عَرَضْتَ عَلَيْهِ الْأَمْرَ دُونَ أَنْ تَذْكُرَ اسْمَ الْمُشْتَرِي", "segs": null, "full_uz": "Shuning uchun agar xaridor ismini aytmasdan taklif qilsang, dedim.", "note": null},
  {"num": 520, "time": "00:39:14,340 --> 00:39:16,700", "arabic": "وَلَكِنْ قُلْ لِي يَا صُهَيْبُ", "segs": null, "full_uz": "Lekin ayt-chi, Suhayb.", "note": null},
  {"num": 521, "time": "00:39:16,700 --> 00:39:19,340", "arabic": "مَا حَاجَتُكَ بِدُكَّانِ ابْنِ حَنْبَلٍ؟", "segs": null, "full_uz": "Ibn Hanbalning do'koniga nima ehtiyoying bor?", "note": null},
  {"num": 522, "time": "00:39:21,280 --> 00:39:24,900", "arabic": "اَلْحَقُّ أَنَّ لَدَيَّ بَعْضَ الْمَالِ وَلَا أَعْرِفُ مَاذَا أَفْعَلُ بِهِ", "segs": null, "full_uz": "Rostini aytsam, menda biroz pul bor, uni nima qilishni bilmayman.", "note": null},
  {"num": 523, "time": "00:39:24,900 --> 00:39:29,360", "arabic": "فَحَدَّثَتْنِي نَفْسِي أَنْ أَشْتَرِيَ دُكَّانًا صَغِيرًا فِي السُّوقِ", "segs": null, "full_uz": "Shuning uchun bozorda kichik bir do'kon sotib olishni o'yladim.", "note": null},
  {"num": 524, "time": "00:39:29,360 --> 00:39:33,340", "arabic": "يَدُرُّ عَلَيَّ مَالًا وَيَكُونُ عَوْنًا لِي فِي قَابِلِ حَيَاتِي", "segs": null, "full_uz": "Menga pul keltirib, kelajak hayotimda yordamchi bo'ladi.", "note": null},
  {"num": 525, "time": "00:39:34,240 --> 00:39:36,320", "arabic": "أَحَقًّا هَذَا هُوَ السَّبَبُ؟", "segs": null, "full_uz": "Rostdan ham sabab shumi?", "note": null},
  {"num": 526, "time": "00:39:36,320 --> 00:39:39,600", "arabic": "وَأَيُّ سَبَبٍ غَيْرُهُ؟", "segs": null, "full_uz": "Bundan boshqa qanaqa sabab bo'lishi mumkin?", "note": null},
  {"num": 527, "time": "00:39:39,600 --> 00:39:40,980", "arabic": "بَغْدَادُ مَلْأَى بِالدَّكَاكِينِ", "segs": null, "full_uz": "Bag'dod do'konlarga to'la.", "note": null},
  {"num": 528, "time": "00:39:40,980 --> 00:39:45,440", "arabic": "فَلِمَ دُكَّانُ ابْنِ حَنْبَلٍ دُونَ غَيْرِهِ؟", "segs": null, "full_uz": "Unda nega aynan Ibn Hanbalning do'koni?", "note": null},
  {"num": 529, "time": "00:39:45,440 --> 00:39:47,580", "arabic": "قَدْ أَكْثَرْتَ عَلَيَّ السُّؤَالَ يَا بَدْرُ", "segs": null, "full_uz": "Menga ko'p savol berib yubording, Badr.", "note": null},
  {"num": 530, "time": "00:39:47,580 --> 00:39:49,500", "arabic": "دَعْنَا مِنْ أَسْئِلَتِكَ الْآنَ", "segs": null, "full_uz": "Hozir savollaringni qo'yib tur.", "note": null},
  {"num": 531, "time": "00:39:49,500 --> 00:39:53,320", "arabic": "وَقُلْ لِي هَلْ سَتُسَاعِدُنِي فِي الْأَمْرِ أَمْ لَا؟", "segs": null, "full_uz": "Ayt-chi, bu ishda menga yordam berasanmi yoki yo'qmi?", "note": null},
  {"num": 532, "time": "00:39:53,320 --> 00:40:06,559", "arabic": "أُرِيدُ أَنْ أَطْلُبَ مِنْكِ طَلَبًا يَا أُمَّ خَالِدٍ", "segs": null, "full_uz": "Sizdan bir iltimosim bor, Umm Xolid.", "note": null},
  {"num": 533, "time": "00:40:06,559 --> 00:40:08,360", "arabic": "تَفَضَّلِي يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Marhamat, Umm Ahmad.", "note": null},
  {"num": 534, "time": "00:40:08,360 --> 00:40:10,860", "arabic": "لَقَدِ انْتَهَيْتُ مِنْ صُنْعِ سَجَّادَةٍ", "segs": null, "full_uz": "Bir gilam to'qishni tugatdim.", "note": null},
  {"num": 535, "time": "00:40:10,860 --> 00:40:13,539", "arabic": "وَأُرِيدُكِ أَنْ تَجِدِي لِي مُشْتَرِيًا", "segs": null, "full_uz": "Va menga xaridor topib berishingizni istayman.", "note": null},
  {"num": 536, "time": "00:40:13,539 --> 00:40:16,820", "arabic": "لَكِ مَا أَرَدْتِ لَكِنَّنِي لَا أَعِدُكِ", "segs": null, "full_uz": "Istaganingiz bo'ladi, lekin sizga va'da bermayman.", "note": null},
  {"num": 537, "time": "00:40:16,820 --> 00:40:20,140", "arabic": "لِأَنَّ الطَّلَبَ قَلِيلٌ عَلَى السَّجَّادِ هَذِهِ الْأَيَّامَ", "segs": null, "full_uz": "Chunki hozirgi kunlarda gilamlarga talab kam.", "note": null},
  {"num": 538, "time": "00:40:20,139 --> 00:40:26,119", "arabic": "سَلِي أَوَّلًا يَا أُمَّ خَالِدٍ وَمِنْ ثَمَّ يَفْعَلُ اللَّهُ مَا يُرِيدُ", "segs": null, "full_uz": "Avval so'rang, Umm Xolid, keyin Alloh xohlaganini qiladi.", "note": null},
  {"num": 539, "time": "00:40:26,119 --> 00:40:31,139", "arabic": "لَوْ كُنْتِ أَطَعْتِنِي وَتَزَوَّجْتِ أَلَمْ يَكُنْ ذَلِكَ خَيْرًا مِمَّا تُعَانِينَ؟", "segs": null, "full_uz": "Agar menga itoat qilib, turmush qurganingda, bu boshingdan kechirayotganingdan yaxshiroq bo'lmasmidi?", "note": null},
  {"num": 540, "time": "00:40:31,139 --> 00:40:35,219", "arabic": "بَلْ إِنِّي لَا أَسْتَبْدِلُ سَعَادَةَ ابْنِي بِكُنُوزِ الدُّنْيَا وَمَا عَلَيْهَا", "segs": null, "full_uz": "Yo'q, men o'g'limning baxtini dunyo xazinalari va undagi barcha narsalarga almashtirmayman.", "note": null},
  {"num": 541, "time": "00:40:35,219 --> 00:40:39,900", "arabic": "فَقَدْ وَهَبْتُ حَيَاتِي بَعْدَ مَوْتِ أَبِيهِ مِنْ أَجْلِ سَعَادَتِهِ", "segs": null, "full_uz": "Otasi vafotidan keyin hayotimni uning baxti uchun bag'ishladim.", "note": null},
  {"num": 542, "time": "00:40:39,900 --> 00:40:44,059", "arabic": "أَدَامَهُ اللَّهُ لَكِ وَأَدَامَكِ لَهُ يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Alloh uni sizga, sizni esa unga abadiy qilsin, Umm Ahmad.", "note": null},
  {"num": 543, "time": "00:40:44,059 --> 00:40:47,579", "arabic": "جَزَاكِ اللَّهُ عَنَّا كُلَّ خَيْرٍ يَا أُمَّ خَالِدٍ", "segs": null, "full_uz": "Alloh sizga bizdan barcha yaxshiliklar bilan mukofot bersin, Umm Xolid.", "note": null},
  {"num": 544, "time": "00:40:47,579 --> 00:40:50,159", "arabic": "وَلَكِنْ لَا تَنْسَيْ لِي", "segs": null, "full_uz": "Lekin meni unutmang.", "note": null},
  {"num": 545, "time": "00:40:50,159 --> 00:40:52,420", "arabic": "جِدِي لِي مُشْتَرِيًا", "segs": null, "full_uz": "Menga xaridor toping.", "note": null},
  {"num": 546, "time": "00:40:52,420 --> 00:40:55,400", "arabic": "سَأَرَى مَا يَكُونُ لَا تَقْلَقِي", "segs": null, "full_uz": "Nima bo'lishini ko'raman, xavotir olmang.", "note": null},
  {"num": 547, "time": "00:40:55,400 --> 00:40:56,980", "arabic": "يَا رَبِّ", "segs": null, "full_uz": "Ey Robbim.", "note": null}
];
if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}